import Database from 'better-sqlite3';
const db = new Database('./data/rental.db');
try {
    db.exec('ALTER TABLE products ADD COLUMN requires_license INTEGER DEFAULT 0;');
} catch (e) { console.log('requires_license exists'); }
try {
    db.exec('ALTER TABLE products ADD COLUMN requires_approval INTEGER DEFAULT 0;');
} catch (e) { console.log('requires_approval exists'); }
db.exec(`CREATE TABLE IF NOT EXISTS "product_documents" (
    "id" text PRIMARY KEY NOT NULL,
    "product_id" text NOT NULL,
    "name" text NOT NULL,
    "url" text NOT NULL,
    "type" text NOT NULL,
    "size" integer NOT NULL,
    "uploaded_at" text NOT NULL,
    FOREIGN KEY ("product_id") REFERENCES "products"("id") ON UPDATE no action ON DELETE no action
);`);
console.log('Migration successful');

"use client";

import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

interface BookingDetail {
    id: string;
    status: string;
    customerName: string;
    customerEmail: string;
    customerPhone: string | null;
    notes: string | null;
    startDate: string;
    endDate: string;
    units: number;
    product: {
        name: string;
        pricePerDay: number;
    };
    totalPrice: number | null;
    discount: number;
    logisticsCost: number;
    laborCost: number;
    customFee: number;
    adminNotes: string | null;
    taxRate: number;
}

const STATUS_LABELS: Record<string, string> = {
    pending_quote: "📥 Pending Quote",
    quote_sent: "📨 Quote Sent",
    changes_requested: "🔄 Changes Requested",
    quote_accepted: "⭐ Quote Accepted",
    approved: "✅ Approved",
    booked: "🎯 Booked",
    cancelled: "❌ Cancelled",
    undelivered: "📉 Undelivered",
};

export default function BookingDetailsPage({ params }: { params: Promise<{ id: string }> }) {
    const resolvedParams = React.use(params);
    const id = resolvedParams.id;
    const router = useRouter();
    const [booking, setBooking] = useState<BookingDetail | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    // Editable form state
    const [pricing, setPricing] = useState({
        discount: 0,
        logisticsCost: 0,
        laborCost: 0,
        customFee: 0,
        adminNotes: "",
    });

    useEffect(() => {
        fetch(`/api/admin/bookings/${id}`)
            .then((r) => r.json())
            .then((data) => {
                setBooking(data);
                setPricing({
                    discount: data.discount || 0,
                    logisticsCost: data.logisticsCost || 0,
                    laborCost: data.laborCost || 0,
                    customFee: data.customFee || 0,
                    adminNotes: data.adminNotes || "",
                });
                setLoading(false);
            })
            .catch(() => setLoading(false));
    }, [id]);

    if (loading) return <div className="p-8 text-[var(--color-slate)]">Loading booking data...</div>;
    if (!booking) return <div className="p-8 text-[var(--color-danger)]">Booking not found</div>;

    // Derived Financials
    const calcDays = (start: string, end: string) => {
        const s = new Date(start);
        const e = new Date(end);
        return Math.max(1, Math.ceil((e.getTime() - s.getTime()) / (1000 * 60 * 60 * 24)) + 1);
    };

    const days = calcDays(booking.startDate, booking.endDate);
    const baseRental = booking.product.pricePerDay * booking.units * days;

    // Apply discount to base rental before adding flat fees
    const discountAmount = baseRental * (pricing.discount / 100);
    const subtotal = baseRental - discountAmount + pricing.logisticsCost + pricing.laborCost + pricing.customFee;
    const tax = subtotal * (booking.taxRate / 100);
    const grandTotal = subtotal + tax;

    const handleSave = async (newStatus?: string) => {
        setSaving(true);
        const payload = {
            ...pricing,
            totalPrice: grandTotal,
            ...(newStatus && { status: newStatus }),
        };

        await fetch(`/api/admin/bookings/${id}`, {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
        });

        if (newStatus) {
            setBooking({ ...booking, status: newStatus });
        }
        setSaving(false);
    };

    return (
        <div className="max-w-4xl max-h-[90vh] pb-12">
            <button onClick={() => router.push('/admin/bookings')} className="text-sm text-[var(--color-slate)] hover:text-white mb-6 block">
                ← Back to Pipeline
            </button>

            <div className="flex items-start justify-between mb-8">
                <div>
                    <h1 className="font-[family-name:var(--font-heading)] text-2xl font-bold text-[var(--color-warm-white)] flex items-center gap-3">
                        Booking {booking.id.split("-")[0].toUpperCase()}
                        <span className="text-xs font-normal px-2.5 py-1 rounded-full glass text-[var(--color-gold)]">
                            {STATUS_LABELS[booking.status] || booking.status}
                        </span>
                    </h1>
                    <p className="text-[var(--color-slate)] text-sm mt-1">Submitted: {new Date(booking.startDate).toLocaleDateString()}</p>
                </div>

                <div className="flex gap-2">
                    {booking.status === "pending_quote" && (
                        <button onClick={() => handleSave("quote_sent")} disabled={saving} className="btn-primary text-sm px-4 py-2">
                            Send Quote to Client
                        </button>
                    )}
                    {["quote_accepted", "pending_quote", "changes_requested"].includes(booking.status) && (
                        <button onClick={() => handleSave("approved")} disabled={saving} className="bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500/30 transition-colors text-sm px-4 py-2 rounded-lg font-medium">
                            Force Approve Booking
                        </button>
                    )}
                    <button onClick={() => handleSave("cancelled")} disabled={saving} className="bg-red-500/10 text-red-400 hover:bg-red-500/20 transition-colors text-sm px-4 py-2 rounded-lg font-medium">
                        Cancel
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Left Col: Request Details */}
                <div className="space-y-6">
                    <div className="glass rounded-xl p-6">
                        <h3 className="font-semibold text-[var(--color-warm-white)] mb-4 border-b border-white/10 pb-2">Client Details</h3>
                        <p className="text-sm font-medium">{booking.customerName}</p>
                        <p className="text-xs text-[var(--color-slate)] mt-1">{booking.customerEmail}</p>
                        {booking.customerPhone && <p className="text-xs text-[var(--color-slate)] mt-1">{booking.customerPhone}</p>}
                        {booking.notes && (
                            <div className="mt-4 p-3 bg-white/5 rounded-lg text-sm text-[var(--color-slate)]">
                                "{booking.notes}"
                            </div>
                        )}
                    </div>

                    <div className="glass rounded-xl p-6">
                        <h3 className="font-semibold text-[var(--color-warm-white)] mb-4 border-b border-white/10 pb-2">Hardware Requested</h3>
                        <p className="font-medium text-[var(--color-gold)]">{booking.product.name}</p>
                        <div className="grid grid-cols-2 gap-4 mt-4 text-sm">
                            <div>
                                <span className="block text-xs text-[var(--color-slate)] mb-1">Dates</span>
                                {booking.startDate} → {booking.endDate}
                            </div>
                            <div>
                                <span className="block text-xs text-[var(--color-slate)] mb-1">Duration</span>
                                {days} Day{days !== 1 ? 's' : ''}
                            </div>
                            <div>
                                <span className="block text-xs text-[var(--color-slate)] mb-1">Quantity</span>
                                {booking.units} Units
                            </div>
                            <div>
                                <span className="block text-xs text-[var(--color-slate)] mb-1">Base Rate</span>
                                {booking.product.pricePerDay} QAR/day
                            </div>
                        </div>
                    </div>
                </div>

                {/* Right Col: Quote Editor */}
                <div className="glass rounded-xl p-6 border border-[var(--color-gold)] border-opacity-20 relative">
                    <h3 className="font-semibold text-[var(--color-warm-white)] mb-4 border-b border-white/10 pb-2 flex justify-between">
                        <span>Quote Builder</span>
                        <a href={`/quote/${booking.id}`} target="_blank" className="text-xs text-[var(--color-gold)] hover:underline font-normal">
                            View Client Form ↗
                        </a>
                    </h3>

                    <div className="space-y-4 mb-6">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-[var(--color-slate)]">Hardware Base Rental</span>
                            <span className="font-medium">{baseRental.toLocaleString()} QAR</span>
                        </div>

                        <div className="flex justify-between items-center text-sm">
                            <label className="text-[var(--color-slate)]">Discount (%)</label>
                            <input
                                type="number"
                                min="0" max="100"
                                value={pricing.discount}
                                onChange={(e) => setPricing({ ...pricing, discount: Number(e.target.value) })}
                                className="w-20 bg-[var(--color-navy-dark)] border border-white/10 rounded px-2 py-1 text-right text-[var(--color-warm-white)] focus:border-[var(--color-gold)] outline-none"
                            />
                        </div>

                        {pricing.discount > 0 && (
                            <div className="flex justify-between items-center text-xs text-[var(--color-success)]">
                                <span>Discount Amount</span>
                                <span>-{discountAmount.toLocaleString()} QAR</span>
                            </div>
                        )}

                        <div className="flex justify-between items-center text-sm pt-4 border-t border-white/5">
                            <label className="text-[var(--color-slate)]">Logistics / Transport (QAR)</label>
                            <input
                                type="number" min="0"
                                value={pricing.logisticsCost}
                                onChange={(e) => setPricing({ ...pricing, logisticsCost: Number(e.target.value) })}
                                className="w-24 bg-[var(--color-navy-dark)] border border-white/10 rounded px-2 py-1 text-right text-[var(--color-warm-white)] focus:border-[var(--color-gold)] outline-none"
                            />
                        </div>

                        <div className="flex justify-between items-center text-sm">
                            <label className="text-[var(--color-slate)]">Labor / Installation (QAR)</label>
                            <input
                                type="number" min="0"
                                value={pricing.laborCost}
                                onChange={(e) => setPricing({ ...pricing, laborCost: Number(e.target.value) })}
                                className="w-24 bg-[var(--color-navy-dark)] border border-white/10 rounded px-2 py-1 text-right text-[var(--color-warm-white)] focus:border-[var(--color-gold)] outline-none"
                            />
                        </div>

                        <div className="flex justify-between items-center text-sm">
                            <label className="text-[var(--color-slate)]">Custom Fees (QAR)</label>
                            <input
                                type="number" min="0"
                                value={pricing.customFee}
                                onChange={(e) => setPricing({ ...pricing, customFee: Number(e.target.value) })}
                                className="w-24 bg-[var(--color-navy-dark)] border border-white/10 rounded px-2 py-1 text-right text-[var(--color-warm-white)] focus:border-[var(--color-gold)] outline-none"
                            />
                        </div>

                        <div className="flex justify-between items-center text-sm pt-4 border-t border-white/5">
                            <span className="text-[var(--color-slate)]">Tax ({booking.taxRate}%)</span>
                            <span className="font-medium">{tax.toLocaleString()} QAR</span>
                        </div>
                    </div>

                    <div className="border-t border-[var(--color-gold)] border-opacity-30 pt-4 flex justify-between items-end mb-6">
                        <span className="text-[var(--color-warm-white)] font-semibold">Grand Total</span>
                        <span className="text-2xl font-bold gradient-text-gold">{grandTotal.toLocaleString()} QAR</span>
                    </div>

                    <div>
                        <label className="block text-xs font-semibold text-[var(--color-slate)] mb-2 uppercase tracking-wide">
                            Message to Client (Included in Quote)
                        </label>
                        <textarea
                            value={pricing.adminNotes}
                            onChange={(e) => setPricing({ ...pricing, adminNotes: e.target.value })}
                            placeholder="Add terms, clarifications, or special instructions here..."
                            rows={3}
                            className="w-full bg-[var(--color-navy-dark)] border border-white/10 rounded-lg px-3 py-2 text-sm text-[var(--color-warm-white)] focus:border-[var(--color-gold)] outline-none resize-none"
                        />
                    </div>

                    <div className="mt-4 flex justify-end">
                        <button
                            onClick={() => handleSave()}
                            disabled={saving}
                            className="text-sm px-4 py-2 rounded-lg bg-white/5 hover:bg-white/10 transition-colors"
                        >
                            {saving ? "Saving..." : "Save Pricing Draft"}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";

interface Booking {
    id: string;
    units: number;
    startDate: string;
    endDate: string;
    startTime: string | null;
    endTime: string | null;
    status: string;
    customerName: string;
    customerEmail: string;
    customerPhone: string | null;
    notes: string | null;
    totalPrice: number | null;
    discount: number | null;
    logisticsCost: number | null;
    taxRate: number | null;
    createdAt: string;
    product: { name: string; slug: string; thumbnailUrl: string | null };
}

const STATUS_LABELS: Record<string, string> = {
    pending_quote: "📥 Pending Quote",
    quote_sent: "📨 Quote Sent",
    changes_requested: "🔄 Changes Requested",
    quote_accepted: "⭐ Quote Accepted",
    approved: "✅ Approved",
    booked: "🎯 Booked",
    cancelled: "❌ Cancelled",
    undelivered: "📉 Undelivered",
};

const STATUS_COLORS: Record<string, string> = {
    pending_quote: "bg-blue-500/10 text-blue-400 border-blue-500/20",
    quote_sent: "bg-yellow-500/10 text-yellow-400 border-yellow-500/20",
    changes_requested: "bg-orange-500/10 text-orange-400 border-orange-500/20",
    quote_accepted: "bg-green-500/10 text-green-400 border-green-500/20",
    approved: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
    booked: "bg-purple-500/10 text-purple-400 border-purple-500/20",
    cancelled: "bg-red-500/10 text-red-400 border-red-500/20 opacity-60",
    undelivered: "bg-slate-500/10 text-slate-400 border-slate-500/20 opacity-60",
};

const PIPELINE_ORDER = ["pending_quote", "quote_sent", "changes_requested", "quote_accepted", "approved", "booked"];

export default function AdminBookingsPage() {
    const [bookings, setBookings] = useState<Booking[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);

    useEffect(() => {
        fetch("/api/admin/bookings")
            .then((r) => r.json())
            .then((data) => { setBookings(data); setLoading(false); })
            .catch(() => setLoading(false));
    }, []);

    const updateStatus = async (id: string, newStatus: string) => {
        const res = await fetch("/api/admin/bookings", {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ id, status: newStatus }),
        });
        const updated = await res.json();
        setBookings((prev) => prev.map((b) => (b.id === id ? { ...b, ...updated } : b)));
        if (selectedBooking?.id === id) {
            setSelectedBooking({ ...selectedBooking, ...updated });
        }
    };

    const groupedBookings = PIPELINE_ORDER.reduce((acc, status) => {
        acc[status] = bookings.filter((b) => b.status === status);
        return acc;
    }, {} as Record<string, Booking[]>);

    return (
        <div>
            <div className="mb-8">
                <h1 className="font-[family-name:var(--font-heading)] text-2xl md:text-3xl font-bold text-[var(--color-warm-white)]">
                    Booking Pipeline
                </h1>
                <p className="text-[var(--color-slate)] text-sm mt-1">
                    {bookings.length} total bookings · Drag or click to advance status
                </p>
            </div>

            {loading ? (
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    {Array.from({ length: 4 }).map((_, i) => (
                        <div key={i} className="pipeline-col animate-pulse">
                            <div className="h-6 bg-[var(--color-navy-lighter)] rounded w-1/2 mb-4" />
                            <div className="h-24 bg-[var(--color-navy-lighter)] rounded-lg" />
                        </div>
                    ))}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
                    {PIPELINE_ORDER.map((status) => (
                        <div key={status} className="pipeline-col">
                            <div className="flex items-center justify-between mb-4">
                                <h3 className="font-[family-name:var(--font-heading)] text-sm font-semibold tracking-wider text-[var(--color-warm-white)]">
                                    {STATUS_LABELS[status]}
                                </h3>
                                <span className="text-xs px-2 py-0.5 rounded-full glass text-[var(--color-slate)]">
                                    {groupedBookings[status]?.length || 0}
                                </span>
                            </div>
                            <div className="space-y-3">
                                {groupedBookings[status]?.map((booking) => (
                                    <div
                                        key={booking.id}
                                        onClick={() => setSelectedBooking(booking)}
                                        className={`rounded-lg p-4 border cursor-pointer transition-all hover:border-[var(--color-gold)] hover:border-opacity-30 ${STATUS_COLORS[status]}`}
                                    >
                                        <div className="flex items-start justify-between mb-2">
                                            <p className="text-sm font-medium">{booking.product.name}</p>
                                            <span className="text-xs opacity-70">{booking.units}×</span>
                                        </div>
                                        <p className="text-xs opacity-70 mb-2">{booking.customerName}</p>
                                        <div className="flex items-center justify-between text-xs opacity-60">
                                            <span>{booking.startDate}</span>
                                            {booking.totalPrice && (
                                                <span className="font-medium">{booking.totalPrice.toLocaleString()} QAR</span>
                                            )}
                                        </div>

                                        {/* Quick status buttons (simplified to Details link since we have a dedicated page now) */}
                                        <div className="flex justify-end mt-3 pt-2 border-t border-current border-opacity-10">
                                            <a
                                                href={`/admin/bookings/${booking.id}`}
                                                className="text-[10px] px-3 py-1.5 rounded glass hover:bg-white hover:bg-opacity-10 transition-colors font-medium text-[var(--color-warm-white)]"
                                                onClick={(e) => e.stopPropagation()}
                                            >
                                                Manage Booking →
                                            </a>
                                        </div>
                                    </div>
                                ))}
                                {(!groupedBookings[status] || groupedBookings[status].length === 0) && (
                                    <div className="text-center py-8 text-xs text-[var(--color-slate)] opacity-50">
                                        No bookings
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Booking Detail Modal */}
            {selectedBooking && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-60 p-6" onClick={() => setSelectedBooking(null)}>
                    <div className="glass rounded-2xl p-8 max-w-md w-full max-h-[80vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center justify-between mb-6">
                            <h3 className="font-[family-name:var(--font-heading)] text-lg font-semibold text-[var(--color-warm-white)]">
                                Booking Details
                            </h3>
                            <button onClick={() => setSelectedBooking(null)} className="text-[var(--color-slate)] hover:text-[var(--color-warm-white)]">
                                ✕
                            </button>
                        </div>
                        <div className="space-y-4 text-sm">
                            <div>
                                <span className="text-[var(--color-slate)]">Product</span>
                                <p className="font-medium text-[var(--color-warm-white)]">{selectedBooking.product.name}</p>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <span className="text-[var(--color-slate)]">Units</span>
                                    <p className="font-medium text-[var(--color-warm-white)]">{selectedBooking.units}</p>
                                </div>
                                <div>
                                    <span className="text-[var(--color-slate)]">Status</span>
                                    <p className="font-medium">{STATUS_LABELS[selectedBooking.status]}</p>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <span className="text-[var(--color-slate)]">Start</span>
                                    <p className="font-medium text-[var(--color-warm-white)]">{selectedBooking.startDate} {selectedBooking.startTime || ""}</p>
                                </div>
                                <div>
                                    <span className="text-[var(--color-slate)]">End</span>
                                    <p className="font-medium text-[var(--color-warm-white)]">{selectedBooking.endDate} {selectedBooking.endTime || ""}</p>
                                </div>
                            </div>
                            <div>
                                <span className="text-[var(--color-slate)]">Customer</span>
                                <p className="font-medium text-[var(--color-warm-white)]">{selectedBooking.customerName}</p>
                                <p className="text-xs text-[var(--color-slate)]">{selectedBooking.customerEmail}</p>
                                {selectedBooking.customerPhone && <p className="text-xs text-[var(--color-slate)]">{selectedBooking.customerPhone}</p>}
                            </div>
                            {selectedBooking.notes && (
                                <div>
                                    <span className="text-[var(--color-slate)]">Notes</span>
                                    <p className="text-[var(--color-warm-white)]">{selectedBooking.notes}</p>
                                </div>
                            )}
                            <div className="grid grid-cols-2 gap-4 pt-2 border-t border-[var(--color-border-subtle)]">
                                <div>
                                    <span className="text-[var(--color-slate)]">Total Price</span>
                                    <p className="font-bold gradient-text-gold text-lg">{selectedBooking.totalPrice?.toLocaleString() || 0} QAR</p>
                                </div>
                                <div>
                                    <span className="text-[var(--color-slate)]">Discount</span>
                                    <p className="font-medium text-[var(--color-warm-white)]">{selectedBooking.discount || 0}%</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

