"use client";

import { useState, useEffect, useCallback } from "react";

interface Category {
    id: string;
    name: string;
    slug: string;
    icon: string | null;
    description: string | null;
    active: boolean;
    productCount: number;
}

const ICONS = ["🏗️", "💡", "🔊", "🪑", "🎤", "🎬", "🎪", "🎭", "🎨", "📦", "🔧", "⚡", "🎵", "🖥️", "🏠"];

export default function AdminCategoriesPage() {
    const [categories, setCategories] = useState<Category[]>([]);
    const [loading, setLoading] = useState(true);
    const [showForm, setShowForm] = useState(false);
    const [editing, setEditing] = useState<Category | null>(null);
    const [error, setError] = useState("");

    // Form state
    const [formName, setFormName] = useState("");
    const [formDescription, setFormDescription] = useState("");
    const [formIcon, setFormIcon] = useState("📦");

    const fetchCategories = useCallback(async () => {
        const res = await fetch("/api/admin/categories");
        const data = await res.json();
        setCategories(data);
        setLoading(false);
    }, []);

    useEffect(() => { fetchCategories(); }, [fetchCategories]);

    const openCreateForm = () => {
        setEditing(null);
        setFormName("");
        setFormDescription("");
        setFormIcon("📦");
        setError("");
        setShowForm(true);
    };

    const openEditForm = (cat: Category) => {
        setEditing(cat);
        setFormName(cat.name);
        setFormDescription(cat.description || "");
        setFormIcon(cat.icon || "📦");
        setError("");
        setShowForm(true);
    };

    const handleSubmit = async () => {
        if (!formName.trim()) { setError("Category name is required"); return; }
        setError("");

        if (editing) {
            // Update
            const res = await fetch("/api/admin/categories", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ id: editing.id, name: formName.trim(), description: formDescription.trim() || null, icon: formIcon }),
            });
            if (!res.ok) { const data = await res.json(); setError(data.error); return; }
        } else {
            // Create
            const res = await fetch("/api/admin/categories", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name: formName.trim(), description: formDescription.trim() || null, icon: formIcon }),
            });
            if (!res.ok) { const data = await res.json(); setError(data.error); return; }
        }

        setShowForm(false);
        fetchCategories();
    };

    const toggleActive = async (cat: Category) => {
        await fetch("/api/admin/categories", {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ id: cat.id, active: !cat.active }),
        });
        fetchCategories();
    };

    const deleteCategory = async (cat: Category) => {
        if (!confirm(`Delete "${cat.name}"? This cannot be undone.`)) return;
        const res = await fetch(`/api/admin/categories?id=${cat.id}`, { method: "DELETE" });
        if (!res.ok) {
            const data = await res.json();
            alert(data.error || "Failed to delete");
            return;
        }
        fetchCategories();
    };

    return (
        <div>
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="font-[family-name:var(--font-heading)] text-2xl md:text-3xl font-bold text-[var(--color-warm-white)]">
                        Categories
                    </h1>
                    <p className="text-[var(--color-slate)] text-sm mt-1">{categories.length} categories · Manage your equipment taxonomy</p>
                </div>
                <button onClick={openCreateForm} className="btn-primary text-sm">
                    + New Category
                </button>
            </div>

            {/* Category Cards */}
            {loading ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {Array.from({ length: 4 }).map((_, i) => (
                        <div key={i} className="glass rounded-xl p-6 animate-pulse">
                            <div className="h-6 bg-[var(--color-navy-lighter)] rounded w-1/2 mb-3" />
                            <div className="h-4 bg-[var(--color-navy-lighter)] rounded w-3/4" />
                        </div>
                    ))}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {categories.map((cat) => (
                        <div key={cat.id} className={`glass rounded-xl p-6 transition-all ${!cat.active ? "opacity-50" : ""}`}>
                            <div className="flex items-start justify-between mb-3">
                                <div className="flex items-center gap-3">
                                    <span className="text-2xl">{cat.icon || "📦"}</span>
                                    <div>
                                        <h3 className="font-[family-name:var(--font-heading)] font-semibold text-[var(--color-warm-white)]">
                                            {cat.name}
                                        </h3>
                                        <span className="text-xs text-[var(--color-slate)] font-mono">/{cat.slug}</span>
                                    </div>
                                </div>

                                {/* Toggle */}
                                <button
                                    onClick={() => toggleActive(cat)}
                                    className={`w-11 h-6 rounded-full transition-all relative shrink-0 ${cat.active ? "bg-[var(--color-gold)]" : "bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)]"
                                        }`}
                                    title={cat.active ? "Active — click to disable" : "Disabled — click to enable"}
                                >
                                    <div className={`w-4 h-4 rounded-full bg-white absolute top-1 transition-all ${cat.active ? "left-6" : "left-1"}`} />
                                </button>
                            </div>

                            {cat.description && (
                                <p className="text-sm text-[var(--color-slate)] mb-3 line-clamp-2">{cat.description}</p>
                            )}

                            <div className="flex items-center justify-between mt-4 pt-3 border-t border-[var(--color-border-subtle)]">
                                <div className="flex items-center gap-4">
                                    <span className="text-xs text-[var(--color-slate)]">
                                        {cat.productCount} product{cat.productCount !== 1 ? "s" : ""}
                                    </span>
                                    <span className={`text-xs px-2 py-0.5 rounded-full ${cat.active ? "bg-green-500/10 text-[var(--color-success)]" : "bg-red-500/10 text-[var(--color-danger)]"
                                        }`}>
                                        {cat.active ? "Active" : "Disabled"}
                                    </span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => openEditForm(cat)}
                                        className="text-xs text-[var(--color-slate)] hover:text-[var(--color-gold)] transition-colors px-2 py-1"
                                    >
                                        Edit
                                    </button>
                                    <button
                                        onClick={() => deleteCategory(cat)}
                                        className="text-xs text-[var(--color-danger)] hover:text-red-400 transition-colors px-2 py-1"
                                    >
                                        Delete
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Create / Edit Modal */}
            {showForm && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-60 p-6" onClick={() => setShowForm(false)}>
                    <div className="glass rounded-2xl p-8 max-w-md w-full" onClick={(e) => e.stopPropagation()}>
                        <h3 className="font-[family-name:var(--font-heading)] text-lg font-semibold text-[var(--color-warm-white)] mb-6">
                            {editing ? "Edit Category" : "Create Category"}
                        </h3>

                        {error && (
                            <div className="mb-4 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-[var(--color-danger)] text-sm">
                                {error}
                            </div>
                        )}

                        <div className="space-y-4">
                            {/* Icon Picker */}
                            <div>
                                <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Icon</label>
                                <div className="flex flex-wrap gap-2">
                                    {ICONS.map((icon) => (
                                        <button
                                            key={icon}
                                            type="button"
                                            onClick={() => setFormIcon(icon)}
                                            className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${formIcon === icon
                                                    ? "bg-[var(--color-gold)] scale-110"
                                                    : "bg-[var(--color-navy-lighter)] hover:bg-[var(--color-navy-light)]"
                                                }`}
                                        >
                                            {icon}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Name */}
                            <div>
                                <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Category Name *</label>
                                <input
                                    type="text"
                                    value={formName}
                                    onChange={(e) => setFormName(e.target.value)}
                                    placeholder="e.g. Special Effects"
                                    className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm"
                                    autoFocus
                                />
                            </div>

                            {/* Description */}
                            <div>
                                <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Description</label>
                                <textarea
                                    value={formDescription}
                                    onChange={(e) => setFormDescription(e.target.value)}
                                    placeholder="Brief description of this equipment category..."
                                    rows={3}
                                    className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm resize-none"
                                />
                            </div>
                        </div>

                        <div className="flex items-center justify-end gap-3 mt-6">
                            <button onClick={() => setShowForm(false)} className="btn-secondary text-sm !py-2 !px-5">
                                Cancel
                            </button>
                            <button onClick={handleSubmit} className="btn-primary text-sm !py-2 !px-5">
                                {editing ? "Save Changes" : "Create Category"}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { format, parseISO } from "date-fns";

type Override = {
    id: string;
    productId: string;
    startDate: string;
    endDate: string;
    unitsOffline: number;
    reason: string;
    createdAt: string;
    product: {
        name: string;
        totalUnits: number;
    };
};

type ProductOption = {
    id: string;
    name: string;
    totalUnits: number;
};

export default function InventoryAdminPage() {
    const [overrides, setOverrides] = useState<Override[]>([]);
    const [products, setProducts] = useState<ProductOption[]>([]);
    const [loading, setLoading] = useState(true);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState("");

    // Form State
    const [productId, setProductId] = useState("");
    const [startDate, setStartDate] = useState("");
    const [endDate, setEndDate] = useState("");
    const [unitsOffline, setUnitsOffline] = useState("1");
    const [reason, setReason] = useState("");

    useEffect(() => {
        Promise.all([
            fetch("/api/admin/inventory").then((res) => res.json()),
            fetch("/api/products").then((res) => res.json()),
        ]).then(([overridesData, productsData]) => {
            setOverrides(overridesData || []);
            setProducts(productsData || []);
            setLoading(false);
        }).catch(err => {
            console.error(err);
            setLoading(false);
        });
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError("");

        if (!productId || !startDate || !endDate || !unitsOffline || !reason) {
            setError("All fields are required.");
            return;
        }

        if (new Date(startDate) > new Date(endDate)) {
            setError("End date must be after start date.");
            return;
        }

        setIsSubmitting(true);

        try {
            const res = await fetch("/api/admin/inventory", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    productId,
                    startDate,
                    endDate,
                    unitsOffline: Number(unitsOffline),
                    reason,
                }),
            });

            if (!res.ok) {
                const data = await res.json();
                throw new Error(data.error || "Failed to create override");
            }

            const newOverride = await res.json();
            setOverrides([newOverride, ...overrides]);

            // Reset form
            setProductId("");
            setStartDate("");
            setEndDate("");
            setUnitsOffline("1");
            setReason("");
        } catch (err: any) {
            setError(err.message);
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Are you sure you want to remove this override? Units will become available again immediately.")) return;

        try {
            const res = await fetch(`/api/admin/inventory?id=${id}`, { method: "DELETE" });
            if (res.ok) {
                setOverrides(overrides.filter((o) => o.id !== id));
            } else {
                alert("Failed to delete override");
            }
        } catch (err) {
            console.error(err);
            alert("Network error");
        }
    };

    if (loading) {
        return <div className="p-8 text-[var(--color-slate)]">Loading inventory data...</div>;
    }

    return (
        <div>
            <header className="mb-8">
                <h1 className="font-[family-name:var(--font-heading)] text-3xl font-bold text-[var(--color-warm-white)]">
                    Inventory Overrides
                </h1>
                <p className="text-[var(--color-slate)] mt-2">
                    Manually take units offline for maintenance or manual reservations without creating a fake booking.
                </p>
            </header>

            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                {/* Left Col: Create Override Form */}
                <div className="xl:col-span-1">
                    <form onSubmit={handleSubmit} className="glass rounded-xl p-6 sticky top-24">
                        <h2 className="font-[family-name:var(--font-heading)] font-semibold text-lg text-[var(--color-gold)] mb-6">
                            Create New Override
                        </h2>

                        {error && (
                            <div className="bg-red-500/10 border border-red-500/20 text-red-500 text-sm p-3 rounded-lg mb-4">
                                {error}
                            </div>
                        )}

                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-[var(--color-slate)] mb-1">Product</label>
                                <select
                                    value={productId}
                                    onChange={(e) => setProductId(e.target.value)}
                                    className="w-full px-4 py-2 bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] rounded-lg text-sm text-[var(--color-warm-white)] focus:outline-none focus:border-[var(--color-gold)]"
                                >
                                    <option value="">Select a product...</option>
                                    {products.map((p) => (
                                        <option key={p.id} value={p.id}>
                                            {p.name} (Max {p.totalUnits})
                                        </option>
                                    ))}
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-[var(--color-slate)] mb-1">Start Date</label>
                                    <input
                                        type="date"
                                        value={startDate}
                                        onChange={(e) => setStartDate(e.target.value)}
                                        className="w-full px-4 py-2 bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] rounded-lg text-sm text-[var(--color-warm-white)] focus:outline-none focus:border-[var(--color-gold)]"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-[var(--color-slate)] mb-1">End Date</label>
                                    <input
                                        type="date"
                                        value={endDate}
                                        onChange={(e) => setEndDate(e.target.value)}
                                        className="w-full px-4 py-2 bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] rounded-lg text-sm text-[var(--color-warm-white)] focus:outline-none focus:border-[var(--color-gold)]"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--color-slate)] mb-1">Units Offline</label>
                                <input
                                    type="number"
                                    min="1"
                                    value={unitsOffline}
                                    onChange={(e) => setUnitsOffline(e.target.value)}
                                    className="w-full px-4 py-2 bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] rounded-lg text-sm text-[var(--color-warm-white)] focus:outline-none focus:border-[var(--color-gold)]"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--color-slate)] mb-1">Reason</label>
                                <input
                                    type="text"
                                    placeholder="e.g. Maintenance, Damaged, Manual Hold"
                                    value={reason}
                                    onChange={(e) => setReason(e.target.value)}
                                    className="w-full px-4 py-2 bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] rounded-lg text-sm text-[var(--color-warm-white)] focus:outline-none focus:border-[var(--color-gold)]"
                                />
                            </div>

                            <button
                                type="submit"
                                disabled={isSubmitting}
                                className="w-full btn-primary mt-2 disabled:opacity-50"
                            >
                                {isSubmitting ? "Creating..." : "Take Offline"}
                            </button>
                        </div>
                    </form>
                </div>

                {/* Right Col: Active Overrides List */}
                <div className="xl:col-span-2">
                    <div className="glass rounded-xl overflow-hidden">
                        <div className="p-6 border-b border-[var(--color-border-subtle)]">
                            <h2 className="font-[family-name:var(--font-heading)] font-semibold text-lg text-[var(--color-warm-white)]">
                                Active & Historical Overrides ({overrides.length})
                            </h2>
                        </div>

                        {overrides.length === 0 ? (
                            <div className="p-8 text-center text-[var(--color-slate)]">
                                No inventory blocks currently active.
                            </div>
                        ) : (
                            <div className="overflow-x-auto">
                                <table className="w-full text-left text-sm">
                                    <thead className="bg-[var(--color-navy-lighter)] text-[var(--color-slate)] uppercase text-xs font-semibold">
                                        <tr>
                                            <th className="px-6 py-4">Product</th>
                                            <th className="px-6 py-4">Date Range</th>
                                            <th className="px-6 py-4">Status</th>
                                            <th className="px-6 py-4 text-center">Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-[var(--color-border-subtle)]">
                                        {overrides.map((override) => {
                                            const today = new Date();
                                            today.setHours(0, 0, 0, 0);
                                            const start = parseISO(override.startDate);
                                            const end = parseISO(override.endDate);

                                            // Status logic
                                            const isPast = end < today;
                                            const isFuture = start > today;
                                            const isActive = !isPast && !isFuture;

                                            return (
                                                <tr key={override.id} className="hover:bg-[var(--color-navy-lighter)]/50 transition-colors group">
                                                    <td className="px-6 py-4">
                                                        <p className="font-medium text-[var(--color-warm-white)]">{override.product?.name || "Unknown Product"}</p>
                                                        <p className="text-xs text-[var(--color-gold)] mt-1">{override.unitsOffline} units blocked</p>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <p className="text-[var(--color-warm-white)]">
                                                            {format(start, "MMM do, yyyy")} - {format(end, "MMM do, yyyy")}
                                                        </p>
                                                        <p className="text-xs text-[var(--color-slate)] mt-1">{override.reason}</p>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        {isActive && <span className="px-2 py-1 text-[10px] font-medium bg-red-500/10 text-red-500 rounded-lg">ACTIVE INVENTORY BLOCK</span>}
                                                        {isFuture && <span className="px-2 py-1 text-[10px] font-medium bg-yellow-500/10 text-yellow-500 rounded-lg">UPCOMING</span>}
                                                        {isPast && <span className="px-2 py-1 text-[10px] font-medium bg-[var(--color-navy-lighter)] text-[var(--color-slate)] rounded-lg">HISTORICAL</span>}
                                                    </td>
                                                    <td className="px-6 py-4 text-center">
                                                        <button
                                                            onClick={() => handleDelete(override.id)}
                                                            className="text-xs text-[var(--color-slate)] hover:text-[var(--color-danger)] transition-colors underline"
                                                        >
                                                            Revoke
                                                        </button>
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useRouter, useParams } from "next/navigation";
import Link from "next/link";

interface Category {
    id: string;
    name: string;
    slug: string;
    active: boolean;
}

interface UploadedFile {
    id: string;
    type: string;
    url: string;
    originalName: string;
    size: number;
}

const CONDITION_OPTIONS = [
    { value: "excellent", label: "Excellent" },
    { value: "good", label: "Good" },
    { value: "maintenance_required", label: "Maintenance Required" },
];

const TYPE_ICONS: Record<string, string> = { image: "🖼️", video: "🎬", model3d: "🎲" };
const TYPE_LABELS: Record<string, string> = { image: "Image", video: "Video", model3d: "3D Model" };

function formatFileSize(bytes: number) {
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export default function EditProductPage() {
    const router = useRouter();
    const params = useParams();
    const productId = params?.id as string;
    const [categories, setCategories] = useState<Category[]>([]);
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    const [success, setSuccess] = useState(false);
    const [realProductId, setRealProductId] = useState<string>("");

    // Media uploads
    const [mediaFiles, setMediaFiles] = useState<UploadedFile[]>([]);
    const [uploading, setUploading] = useState(false);
    const [uploadProgress, setUploadProgress] = useState("");
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Document uploads
    const [documentFiles, setDocumentFiles] = useState<UploadedFile[]>([]);
    const [documentUploading, setDocumentUploading] = useState(false);
    const [documentUploadProgress, setDocumentUploadProgress] = useState("");
    const documentInputRef = useRef<HTMLInputElement>(null);

    // Form state
    const [form, setForm] = useState({
        name: "",
        categoryId: "",
        shortDescription: "",
        description: "",
        dimensions: "",
        weight: "",
        powerRequirements: "",
        materials: "",
        pricePerDay: "",
        pricePerHour: "",
        totalUnits: "1",
        condition: "excellent",
        installTime: "0",
        dismantleTime: "0",
        cleaningTime: "0",
        manpower: "",
        tools: "",
        thumbnailUrl: "",
        featured: false,
        requiresLicense: false,
        requiresApproval: false,
    });

    useEffect(() => {
        // Fetch categories
        fetch("/api/categories")
            .then((r) => r.json())
            .then((data) => setCategories(data.filter((c: Category) => c.active !== false)))
            .catch(console.error);

        // Fetch existing product data
        if (productId) {
            fetch(`/api/products/${productId}`)
                .then(r => r.json())
                .then(data => {
                    if (!data || data.error) return;
                    setForm({
                        name: data.name || "",
                        categoryId: data.categoryId || "",
                        shortDescription: data.shortDescription || "",
                        description: data.description || "",
                        dimensions: data.dimensions || "",
                        weight: data.weight || "",
                        powerRequirements: data.powerRequirements || "",
                        materials: data.materials || "",
                        pricePerDay: data.pricePerDay?.toString() || "",
                        pricePerHour: data.pricePerHour?.toString() || "",
                        totalUnits: data.totalUnits?.toString() || "1",
                        condition: data.condition || "excellent",
                        installTime: data.installTime?.toString() || "0",
                        dismantleTime: data.dismantleTime?.toString() || "0",
                        cleaningTime: data.cleaningTime?.toString() || "0",
                        manpower: data.manpower || "",
                        tools: data.tools || "",
                        thumbnailUrl: data.thumbnailUrl || "",
                        featured: data.featured || false,
                        requiresLicense: !!data.requiresLicense,
                        requiresApproval: !!data.requiresApproval,
                    });
                    setRealProductId(data.id);
                    if (data.media) {
                        setMediaFiles(data.media.map((m: any) => ({
                            id: m.id, type: m.type, url: m.url, originalName: m.alt || m.type, size: 0
                        })));
                    }
                    if (data.documents) {
                        setDocumentFiles(data.documents.map((d: any) => ({
                            id: d.id, type: d.type, url: d.url, originalName: d.name, size: d.size || 0
                        })));
                    }
                })
                .catch(console.error);
        }
    }, [productId]);

    const updateField = (field: string, value: string | boolean) => {
        setForm((prev) => ({ ...prev, [field]: value }));
        setError("");
    };

    // ─── Media Upload ───
    const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        setUploading(true);
        setUploadProgress(`Uploading ${files.length} file${files.length > 1 ? "s" : ""}...`);

        const formData = new FormData();
        for (let i = 0; i < files.length; i++) {
            formData.append("files", files[i]);
        }

        try {
            const res = await fetch("/api/upload", { method: "POST", body: formData });
            const data = await res.json();

            if (!res.ok) {
                setError(data.error || "Upload failed");
            } else if (data.files) {
                setMediaFiles((prev) => [...prev, ...data.files]);

                // Auto-set thumbnail to first uploaded image
                const firstImage = data.files.find((f: UploadedFile) => f.type === "image");
                if (firstImage && !form.thumbnailUrl) {
                    setForm((prev) => ({ ...prev, thumbnailUrl: firstImage.url }));
                }
            }
        } catch {
            setError("Upload failed — network error");
        }

        setUploading(false);
        setUploadProgress("");
        // Reset file input
        if (fileInputRef.current) fileInputRef.current.value = "";
    };

    const removeMedia = (id: string) => {
        const removed = mediaFiles.find((f) => f.id === id);
        setMediaFiles((prev) => prev.filter((f) => f.id !== id));
        // Clear thumbnail if it was the removed file
        if (removed && form.thumbnailUrl === removed.url) {
            const nextImage = mediaFiles.find((f) => f.id !== id && f.type === "image");
            setForm((prev) => ({ ...prev, thumbnailUrl: nextImage?.url || "" }));
        }
    };

    const setAsThumbnail = (url: string) => {
        setForm((prev) => ({ ...prev, thumbnailUrl: url }));
    };

    // ─── Document Upload ───
    const handleDocumentSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        setDocumentUploading(true);
        setDocumentUploadProgress(`Uploading ${files.length} document${files.length > 1 ? "s" : ""}...`);

        const formData = new FormData();
        for (let i = 0; i < files.length; i++) {
            formData.append("files", files[i]);
        }

        try {
            const res = await fetch("/api/upload", { method: "POST", body: formData });
            const data = await res.json();

            if (!res.ok) {
                setError(data.error || "Upload failed");
            } else if (data.files) {
                setDocumentFiles((prev) => [...prev, ...data.files]);
            }
        } catch {
            setError("Upload failed — network error");
        }

        setDocumentUploading(false);
        setDocumentUploadProgress("");
        if (documentInputRef.current) documentInputRef.current.value = "";
    };

    const removeDocument = (id: string) => {
        setDocumentFiles((prev) => prev.filter((f) => f.id !== id));
    };

    // ─── Submit ───
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError("");

        if (!form.name.trim()) { setError("Product name is required"); return; }
        if (!form.categoryId) { setError("Please select a category"); return; }
        if (!form.pricePerDay || Number(form.pricePerDay) <= 0) { setError("Price per day must be greater than 0"); return; }
        if (!form.totalUnits || Number(form.totalUnits) < 1) { setError("At least 1 unit is required"); return; }

        setSaving(true);

        try {
            const res = await fetch("/api/admin/products", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    id: realProductId || productId,
                    ...form,
                    pricePerDay: Number(form.pricePerDay),
                    pricePerHour: form.pricePerHour ? Number(form.pricePerHour) : null,
                    totalUnits: Number(form.totalUnits),
                    installTime: Number(form.installTime),
                    dismantleTime: Number(form.dismantleTime),
                    cleaningTime: Number(form.cleaningTime),
                    media: mediaFiles.map((f, i) => ({
                        id: f.id,
                        type: f.type,
                        url: f.url,
                        alt: f.originalName,
                        sortOrder: i,
                    })),
                    documents: documentFiles.map(f => ({
                        id: f.id,
                        type: f.type,
                        url: f.url,
                        originalName: f.originalName,
                        size: f.size
                    })),
                }),
            });

            if (!res.ok) {
                const data = await res.json();
                throw new Error(data.error || "Failed to create product");
            }

            setSuccess(true);
            setTimeout(() => router.push("/admin/products"), 1500);
        } catch (err: unknown) {
            setError(err instanceof Error ? err.message : "Something went wrong");
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="max-w-4xl">
            {/* Header */}
            <div className="flex items-center gap-4 mb-8">
                <Link
                    href="/admin/products"
                    className="w-10 h-10 rounded-lg bg-[var(--color-surface)] border border-[var(--color-border-subtle)] flex items-center justify-center text-[var(--color-slate)] hover:text-[var(--color-gold)] hover:border-[var(--color-gold)] transition-all"
                >
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <polyline points="15 18 9 12 15 6" />
                    </svg>
                </Link>
                <div>
                    <h1 className="font-[family-name:var(--font-heading)] text-2xl md:text-3xl font-bold text-[var(--color-warm-white)]">
                        Edit Product
                    </h1>
                    <p className="text-[var(--color-slate)] text-sm mt-0.5">Update equipment details</p>
                </div>
            </div>

            {/* Success */}
            {success && (
                <div className="mb-6 p-4 rounded-xl bg-green-500/10 border border-green-500/20 text-[var(--color-success)] flex items-center gap-3">
                    <div className="dot-available" />
                    <span className="text-sm font-medium">Product created successfully! Redirecting...</span>
                </div>
            )}

            {/* Error */}
            {error && (
                <div className="mb-6 p-4 rounded-xl bg-red-500/10 border border-red-500/20 text-[var(--color-danger)] flex items-center gap-3">
                    <div className="dot-unavailable" />
                    <span className="text-sm font-medium">{error}</span>
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-8">

                {/* ─── BASIC INFO ─── */}
                <section className="glass rounded-xl p-6">
                    <h2 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-5">
                        BASIC INFORMATION
                    </h2>
                    <div className="space-y-4">
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Product Name *</label>
                            <input type="text" value={form.name} onChange={(e) => updateField("name", e.target.value)}
                                placeholder="e.g. Heavy-Duty Stage Platform 4x8"
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                        </div>

                        <div className="flex gap-4 items-end">
                            <div className="flex-1">
                                <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Category *</label>
                                <select value={form.categoryId} onChange={(e) => updateField("categoryId", e.target.value)}
                                    className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm appearance-none cursor-pointer">
                                    <option value="" className="bg-[var(--color-navy)]">Select a category...</option>
                                    {categories.map((cat) => (
                                        <option key={cat.id} value={cat.id} className="bg-[var(--color-navy)]">{cat.name}</option>
                                    ))}
                                </select>
                            </div>
                            <Link href="/admin/categories" className="text-xs text-[var(--color-gold)] hover:underline py-3 whitespace-nowrap">
                                Manage Categories →
                            </Link>
                        </div>

                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Short Description</label>
                            <input type="text" value={form.shortDescription} onChange={(e) => updateField("shortDescription", e.target.value)}
                                placeholder="One-line summary for catalog cards"
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                        </div>

                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Full Description</label>
                            <textarea value={form.description} onChange={(e) => updateField("description", e.target.value)}
                                placeholder="Detailed product description for the detail page..."
                                rows={4}
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm resize-none" />
                        </div>

                        <div className="flex items-center gap-3">
                            <button type="button" onClick={() => updateField("featured", !form.featured)}
                                className={`w-11 h-6 rounded-full transition-all relative ${form.featured ? "bg-[var(--color-gold)]" : "bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)]"}`}>
                                <div className={`w-4 h-4 rounded-full bg-white absolute top-1 transition-all ${form.featured ? "left-6" : "left-1"}`} />
                            </button>
                            <span className="text-sm text-[var(--color-slate)]">Featured product (shown on homepage)</span>
                        </div>
                    </div>
                </section>

                {/* ─── MEDIA UPLOAD ─── */}
                <section className="glass rounded-xl p-6">
                    <h2 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-2">
                        MEDIA FILES
                    </h2>
                    <p className="text-xs text-[var(--color-slate)] mb-5">
                        Upload product images, videos, and 3D models (GLB/GLTF). First image auto-sets as thumbnail.
                    </p>

                    {/* Upload Zone */}
                    <div
                        className="border-2 border-dashed border-[var(--color-border-subtle)] rounded-xl p-8 text-center hover:border-[var(--color-gold)] transition-colors cursor-pointer relative"
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <input
                            ref={fileInputRef}
                            type="file"
                            multiple
                            accept="image/jpeg,image/png,image/webp,image/avif,image/gif,video/mp4,video/webm,.glb,.gltf"
                            className="hidden"
                            onChange={handleFileSelect}
                        />
                        {uploading ? (
                            <div>
                                <div className="w-8 h-8 border-2 border-[var(--color-gold)] border-t-transparent rounded-full animate-spin mx-auto mb-3" />
                                <p className="text-sm text-[var(--color-gold)]">{uploadProgress}</p>
                            </div>
                        ) : (
                            <>
                                <div className="flex items-center justify-center gap-3 text-3xl mb-3">
                                    <span>🖼️</span><span>🎬</span><span>🎲</span>
                                </div>
                                <p className="text-sm font-medium text-[var(--color-warm-white)]">
                                    Click to upload or drag & drop
                                </p>
                                <p className="text-xs text-[var(--color-slate)] mt-1">
                                    Images (JPG, PNG, WebP · 10MB) · Videos (MP4, WebM · 200MB) · 3D Models (GLB, GLTF · 50MB)
                                </p>
                            </>
                        )}
                    </div>

                    {/* Uploaded Files Grid */}
                    {mediaFiles.length > 0 && (
                        <div className="mt-5 space-y-3">
                            <div className="text-xs text-[var(--color-slate)] font-medium">
                                {mediaFiles.length} file{mediaFiles.length !== 1 ? "s" : ""} uploaded
                            </div>
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                {mediaFiles.map((file) => (
                                    <div key={file.id} className="rounded-lg bg-[var(--color-navy-lighter)] overflow-hidden group">
                                        {/* Preview */}
                                        {file.type === "image" ? (
                                            <div className="h-32 bg-cover bg-center relative" style={{ backgroundImage: `url(${file.url})` }}>
                                                {form.thumbnailUrl === file.url && (
                                                    <div className="absolute top-2 left-2 text-[10px] px-2 py-0.5 rounded bg-[var(--color-gold)] text-[var(--color-navy)] font-semibold">
                                                        THUMBNAIL
                                                    </div>
                                                )}
                                            </div>
                                        ) : (
                                            <div className="h-32 flex items-center justify-center bg-[var(--color-navy)]">
                                                <span className="text-4xl">{TYPE_ICONS[file.type]}</span>
                                            </div>
                                        )}
                                        {/* Info */}
                                        <div className="p-3">
                                            <p className="text-xs text-[var(--color-warm-white)] font-medium truncate">{file.originalName}</p>
                                            <div className="flex items-center justify-between mt-1.5">
                                                <div className="flex items-center gap-2">
                                                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-[var(--color-navy)] text-[var(--color-slate)]">
                                                        {TYPE_LABELS[file.type]}
                                                    </span>
                                                    <span className="text-[10px] text-[var(--color-slate)]">{formatFileSize(file.size)}</span>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    {file.type === "image" && form.thumbnailUrl !== file.url && (
                                                        <button type="button" onClick={() => setAsThumbnail(file.url)}
                                                            className="text-[10px] text-[var(--color-gold)] hover:underline">
                                                            Set thumbnail
                                                        </button>
                                                    )}
                                                    <button type="button" onClick={() => removeMedia(file.id)}
                                                        className="text-[10px] text-[var(--color-danger)] hover:underline ml-2">
                                                        Remove
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </section>

                {/* ─── TECHNICAL SPECS ─── */}
                <section className="glass rounded-xl p-6">
                    <h2 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-5">
                        TECHNICAL SPECIFICATIONS
                    </h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Dimensions</label>
                            <input type="text" value={form.dimensions} onChange={(e) => updateField("dimensions", e.target.value)}
                                placeholder='e.g. 4ft × 8ft × 16-48in'
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                        </div>
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Weight</label>
                            <input type="text" value={form.weight} onChange={(e) => updateField("weight", e.target.value)}
                                placeholder="e.g. 185 lbs per section"
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                        </div>
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Power Requirements</label>
                            <input type="text" value={form.powerRequirements} onChange={(e) => updateField("powerRequirements", e.target.value)}
                                placeholder="e.g. 800W, 100-240V AC"
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                        </div>
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Materials</label>
                            <input type="text" value={form.materials} onChange={(e) => updateField("materials", e.target.value)}
                                placeholder="e.g. Aircraft-grade 6061-T6 Aluminum"
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                        </div>
                    </div>
                </section>

                {/* ─── PRICING & INVENTORY ─── */}
                <section className="glass rounded-xl p-6">
                    <h2 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-5">
                        PRICING & INVENTORY
                    </h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Price Per Day (QAR) *</label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--color-gold)] text-xs font-semibold">QAR</span>
                                <input type="number" step="0.01" min="0" value={form.pricePerDay} onChange={(e) => updateField("pricePerDay", e.target.value)}
                                    placeholder="0.00"
                                    className="w-full pl-14 pr-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                            </div>
                        </div>
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Price Per Hour (QAR)</label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--color-gold)] text-xs font-semibold">QAR</span>
                                <input type="number" step="0.01" min="0" value={form.pricePerHour} onChange={(e) => updateField("pricePerHour", e.target.value)}
                                    placeholder="Optional"
                                    className="w-full pl-14 pr-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                            </div>
                        </div>
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Total Units in Fleet *</label>
                            <input type="number" min="1" value={form.totalUnits} onChange={(e) => updateField("totalUnits", e.target.value)}
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm" />
                        </div>
                        <div>
                            <label className="text-xs text-[var(--color-slate)] mb-1.5 block font-medium">Condition</label>
                            <select value={form.condition} onChange={(e) => updateField("condition", e.target.value)}
                                className="w-full px-4 py-3 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] focus:border-[var(--color-gold)] focus:outline-none transition-colors text-sm appearance-none cursor-pointer">
                                {CONDITION_OPTIONS.map((opt) => (
                                    <option key={opt.value} value={opt.value} className="bg-[var(--color-navy)]">{opt.label}</option>
                                ))}
                            </select>
                        </div>
                    </div>
                </section>

                {/* ─── COMPLIANCE & APPROVALS ─── */}
                <section className="glass rounded-xl p-6">
                    <h2 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-5">
                        COMPLIANCE & APPROVALS
                    </h2>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                        <div className="flex items-center gap-3">
                            <button type="button" onClick={() => updateField("requiresLicense", !form.requiresLicense)}
                                className={`w-11 h-6 rounded-full transition-all relative ${form.requiresLicense ? "bg-[var(--color-gold)]" : "bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)]"}`}>
                                <div className={`w-4 h-4 rounded-full bg-white absolute top-1 transition-all ${form.requiresLicense ? "left-6" : "left-1"}`} />
                            </button>
                            <div>
                                <span className="text-sm font-medium text-[var(--color-warm-white)] block">Requires License</span>
                                <span className="text-xs text-[var(--color-slate)]">Operator requires valid license</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            <button type="button" onClick={() => updateField("requiresApproval", !form.requiresApproval)}
                                className={`w-11 h-6 rounded-full transition-all relative ${form.requiresApproval ? "bg-[var(--color-gold)]" : "bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)]"}`}>
                                <div className={`w-4 h-4 rounded-full bg-white absolute top-1 transition-all ${form.requiresApproval ? "left-6" : "left-1"}`} />
                            </button>
                            <div>
                                <span className="text-sm font-medium text-[var(--color-warm-white)] block">Municipal Approval</span>
                                <span className="text-xs text-[var(--color-slate)]">Requires venue/government clearance</span>
                            </div>
                        </div>
                    </div>

                    <p className="text-xs text-[var(--color-slate)] mb-3">
                        Upload compliance documents, permits, or safety manuals (PDF/DOC, max 20MB)
                    </p>

                    <div
                        className="border-2 border-dashed border-[var(--color-border-subtle)] bg-[var(--color-navy-lighter)] rounded-xl py-6 px-4 text-center hover:border-[var(--color-gold)] transition-colors cursor-pointer relative"
                        onClick={() => documentInputRef.current?.click()}
                    >
                        <input
                            ref={documentInputRef}
                            type="file"
                            multiple
                            accept=".pdf,.doc,.docx,text/plain"
                            className="hidden"
                            onChange={handleDocumentSelect}
                        />
                        {documentUploading ? (
                            <div>
                                <div className="w-6 h-6 border-2 border-[var(--color-gold)] border-t-transparent rounded-full animate-spin mx-auto mb-2" />
                                <p className="text-xs text-[var(--color-gold)]">{documentUploadProgress}</p>
                            </div>
                        ) : (
                            <>
                                <div className="text-2xl mb-2">📄</div>
                                <p className="text-sm font-medium text-[var(--color-warm-white)]">
                                    Click to upload documents
                                </p>
                            </>
                        )}
                    </div>

                    {documentFiles.length > 0 && (
                        <div className="mt-4 space-y-2">
                            {documentFiles.map((file) => (
