import { db } from "@/lib/db";
import { products, categories, productMedia, safetyCertificates, installationGuides, productDocuments } from "@/lib/db/schema";
import { eq } from "drizzle-orm";
import { NextRequest, NextResponse } from "next/server";
import { v4 as uuid } from "uuid";

export async function GET() {
    const result = await db.query.products.findMany({
        with: {
            category: { columns: { name: true, slug: true } },
            media: true,
            safetyCertificates: true,
        },
    });
    return NextResponse.json(result);
}

export async function POST(req: NextRequest) {
    const body = await req.json();
    const now = new Date().toISOString();

    const slug = body.name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/(^-|-$)/g, "");

    const product = {
        id: uuid(),
        categoryId: body.categoryId,
        name: body.name,
        slug,
        shortDescription: body.shortDescription || null,
        description: body.description || null,
        dimensions: body.dimensions || null,
        weight: body.weight || null,
        powerRequirements: body.powerRequirements || null,
        materials: body.materials || null,
        pricePerDay: Number(body.pricePerDay),
        pricePerHour: body.pricePerHour ? Number(body.pricePerHour) : null,
        totalUnits: Number(body.totalUnits) || 1,
        condition: body.condition || "excellent",
        installTime: Number(body.installTime) || 0,
        dismantleTime: Number(body.dismantleTime) || 0,
        cleaningTime: Number(body.cleaningTime) || 0,
        manpower: body.manpower || null,
        tools: body.tools || null,
        thumbnailUrl: body.thumbnailUrl || null,
        featured: body.featured || false,
        requiresLicense: body.requiresLicense || false,
        requiresApproval: body.requiresApproval || false,
        createdAt: now,
        updatedAt: now,
    };

    await db.insert(products).values(product);

    // Insert uploaded media records
    if (body.media && Array.isArray(body.media) && body.media.length > 0) {
        for (const m of body.media) {
            await db.insert(productMedia).values({
                id: m.id || uuid(),
                productId: product.id,
                type: m.type,
                url: m.url,
                thumbnailUrl: m.thumbnailUrl || null,
                alt: m.alt || null,
                sortOrder: m.sortOrder || 0,
            });
        }
    }

    // Insert uploaded document records
    if (body.documents && Array.isArray(body.documents) && body.documents.length > 0) {
        for (const doc of body.documents) {
            await db.insert(productDocuments).values({
                id: doc.id || uuid(),
                productId: product.id,
                name: doc.originalName || doc.name || "Document",
                url: doc.url,
                type: doc.type || "document",
                size: doc.size || 0,
                uploadedAt: now,
            });
        }
    }

    return NextResponse.json(product, { status: 201 });
}

export async function PUT(req: NextRequest) {
    const body = await req.json();
    const { id, media, documents, ...updates } = body;

    if (!id) {
        return NextResponse.json({ error: "Product ID required" }, { status: 400 });
    }

    updates.updatedAt = new Date().toISOString();
    await db.update(products).set(updates).where(eq(products.id, id));

    // Reconstruct media relations
    if (media && Array.isArray(media)) {
        await db.delete(productMedia).where(eq(productMedia.productId, id));
        for (const m of media) {
            await db.insert(productMedia).values({
                id: m.id || uuid(),
                productId: id,
                type: m.type,
                url: m.url,
                thumbnailUrl: m.thumbnailUrl || null,
                alt: m.alt || null,
                sortOrder: m.sortOrder || 0,
            });
        }
    }

    // Reconstruct document relations
    if (documents && Array.isArray(documents)) {
        await db.delete(productDocuments).where(eq(productDocuments.productId, id));
        for (const doc of documents) {
            await db.insert(productDocuments).values({
                id: doc.id || uuid(),
                productId: id,
                name: doc.originalName || doc.name || "Document",
                url: doc.url,
                type: doc.type || "document",
                size: doc.size || 0,
                uploadedAt: new Date().toISOString(),
            });
        }
    }

    return NextResponse.json({ success: true });
}

export async function DELETE(req: NextRequest) {
    const { searchParams } = new URL(req.url);
    const id = searchParams.get("id");

    if (!id) {
        return NextResponse.json({ error: "Product ID required" }, { status: 400 });
    }

    // Delete related data first
    await db.delete(productMedia).where(eq(productMedia.productId, id));
    await db.delete(productDocuments).where(eq(productDocuments.productId, id));
    await db.delete(safetyCertificates).where(eq(safetyCertificates.productId, id));
    await db.delete(installationGuides).where(eq(installationGuides.productId, id));
    await db.delete(products).where(eq(products.id, id));

    return NextResponse.json({ success: true });
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { users } from "@/lib/db/schema";
import { eq, and, or } from "drizzle-orm";
import { signToken } from "@/lib/auth";
import { cookies } from "next/headers";

export async function POST(req: Request) {
    try {
        const body = await req.json();
        const { email, password } = body;

        if (!email || !password) {
            return NextResponse.json(
                { error: "Email and password are required" },
                { status: 400 }
            );
        }

        // Fallback to phone number for users auto-registered before password field was added
        const [user] = await db
            .select()
            .from(users)
            .where(
                and(
                    eq(users.email, email.toLowerCase()),
                    or(
                        eq(users.password, password),
                        eq(users.phoneNumber, password)
                    )
                )
            )
            .limit(1);

        if (!user) {
            return NextResponse.json(
                { error: "Invalid credentials. If you requested a quote, your password is the phone number you provided." },
                { status: 401 }
            );
        }

        const token = await signToken({
            id: user.id,
            email: user.email,
            role: user.role,
        });

        const cookieStore = await cookies();
        cookieStore.set("envoy_session", token, {
            httpOnly: true,
            secure: process.env.NODE_ENV === "production",
            sameSite: "lax",
            maxAge: 7 * 24 * 60 * 60, // 7 days
            path: "/",
        });

        return NextResponse.json({
            success: true,
            user: {
                id: user.id,
                name: user.name,
                email: user.email,
                role: user.role,
            },
        });
    } catch (error: any) {
        console.error("Login endpoint error:", error);
        return NextResponse.json(
            { error: "Internal server error" },
            { status: 500 }
        );
    }
}

