import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { users } from "@/lib/db/schema";
import { eq } from "drizzle-orm";
import { v4 as uuid } from "uuid";

export async function POST(req: Request) {
    try {
        const body = await req.json();
        const { email, password, name, phoneNumber } = body;

        if (!email || !password || !name) {
            return NextResponse.json(
                { error: "Name, email, and password are required" },
                { status: 400 }
            );
        }

        const normalizedEmail = email.trim().toLowerCase();

        // Check if user exists
        const existingUsers = await db.select().from(users).where(eq(users.email, normalizedEmail)).limit(1);

        if (existingUsers.length > 0) {
            return NextResponse.json(
                { error: "Email is already registered" },
                { status: 409 }
            );
        }

        const targetUserId = uuid();
        await db.insert(users).values({
            id: targetUserId,
            name: name.trim(),
            email: normalizedEmail,
            phoneNumber: phoneNumber || "",
            password: password,
            role: "client",
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
        });

        return NextResponse.json({ success: true, message: "Account created successfully" });

    } catch (error: any) {
        console.error("Signup endpoint error:", error);
        return NextResponse.json(
            { error: "Internal server error" },
            { status: 500 }
        );
    }
}

import { db } from "@/lib/db";
import { cartItems, products } from "@/lib/db/schema";
import { eq, and } from "drizzle-orm";
import { NextRequest, NextResponse } from "next/server";
import { v4 as uuid } from "uuid";

const SESSION_COOKIE = "rental_session";

function getSessionId(req: NextRequest): string {
    return req.cookies.get(SESSION_COOKIE)?.value || uuid();
}

export async function GET(req: NextRequest) {
    const sessionId = getSessionId(req);

    const items = await db.query.cartItems.findMany({
        where: eq(cartItems.sessionId, sessionId),
        with: {
            product: {
                columns: {
                    id: true,
                    name: true,
                    slug: true,
                    pricePerDay: true,
                    pricePerHour: true,
                    thumbnailUrl: true,
                    dimensions: true,
                },
            },
        },
    });

    const response = NextResponse.json(items);
    response.cookies.set(SESSION_COOKIE, sessionId, {
        httpOnly: true,
        sameSite: "lax",
        maxAge: 60 * 60 * 24 * 7, // 7 days
    });
    return response;
}

export async function POST(req: NextRequest) {
    const sessionId = getSessionId(req);
    const body = await req.json();

    const { productId, quantity, startDate, endDate, startTime, endTime } = body;

    if (!productId || !quantity || !startDate || !endDate) {
        return NextResponse.json(
            { error: "Missing required fields" },
            { status: 400 }
        );
    }

    // Check if same product with same dates already in cart
    const existing = await db.query.cartItems.findFirst({
        where: and(
            eq(cartItems.sessionId, sessionId),
            eq(cartItems.productId, productId),
            eq(cartItems.startDate, startDate),
            eq(cartItems.endDate, endDate),
        ),
    });

    if (existing) {
        // Update quantity
        await db
            .update(cartItems)
            .set({ quantity: existing.quantity + Number(quantity) })
            .where(eq(cartItems.id, existing.id));
    } else {
        await db.insert(cartItems).values({
            id: uuid(),
            sessionId,
            productId,
            quantity: Number(quantity),
            startDate,
            endDate,
            startTime: startTime || null,
            endTime: endTime || null,
            createdAt: new Date().toISOString(),
        });
    }

    const response = NextResponse.json({ success: true });
    response.cookies.set(SESSION_COOKIE, sessionId, {
        httpOnly: true,
        sameSite: "lax",
        maxAge: 60 * 60 * 24 * 7,
    });
    return response;
}

export async function DELETE(req: NextRequest) {
    const sessionId = getSessionId(req);
    const { searchParams } = new URL(req.url);
    const itemId = searchParams.get("id");

    if (itemId) {
        await db
            .delete(cartItems)
            .where(and(eq(cartItems.id, itemId), eq(cartItems.sessionId, sessionId)));
    } else {
        // Clear entire cart
        await db.delete(cartItems).where(eq(cartItems.sessionId, sessionId));
    }

    return NextResponse.json({ success: true });
}

import { db } from "@/lib/db";
import { bookings } from "@/lib/db/schema";
import { eq } from "drizzle-orm";
import { NextResponse } from "next/server";

export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }) {
    try {
        const { id } = await params;
        const booking = await db.query.bookings.findFirst({
            where: eq(bookings.id, id),
            with: {
                product: {
                    columns: { name: true, slug: true, thumbnailUrl: true, pricePerDay: true },
                },
            },
        });

        if (!booking) {
            return NextResponse.json({ error: "Quote not found" }, { status: 404 });
        }

        // Security / Privacy: we only return the booking data if the status allows public review
        // (E.g., quote_sent, changes_requested, quote_accepted, approved, booked)
        // Hidden if still 'pending_quote' internal drafting.
        if (booking.status === "pending_quote" || booking.status === "cancelled" || booking.status === "undelivered") {
            return NextResponse.json({ error: "Quote is currently unavailable." }, { status: 403 });
        }

        return NextResponse.json(booking);
    } catch (error) {
        console.error("Client Quote GET Error:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

export async function PATCH(request: Request, { params }: { params: Promise<{ id: string }> }) {
    try {
        const { id } = await params;
        const body = await request.json();

        // Client can only update status (accept/request changes) and their own notes
        const { status, clientNotes } = body;

        // Ensure status transitions are legal for a client to do
        if (!["quote_accepted", "changes_requested"].includes(status) && status !== undefined) {
            return NextResponse.json({ error: "Invalid status transition" }, { status: 400 });
        }

        const updateData: any = {};
        if (status !== undefined) updateData.status = status;
        if (clientNotes !== undefined) updateData.clientNotes = clientNotes;

        updateData.updatedAt = new Date().toISOString();

        await db.update(bookings)
            .set(updateData)
            .where(eq(bookings.id, id));

        return NextResponse.json({ success: true });
    } catch (error) {
        console.error("Client Quote PATCH Error:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

