"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import dynamic from "next/dynamic";
import { Footer } from "@/components/Footer";
import Link from "next/link";
import AvailabilityTimeline from "@/components/product/AvailabilityTimeline";

// Lazy-load heavy components — only mount when tab is active
// Lazy-load heavy components — only mount when tab is active
const ModelViewer = dynamic<{ url?: string }>(() => import("@/components/product/ModelViewer"), {
    ssr: false,
    loading: () => <MediaLoadingPlaceholder label="Loading 3D Model..." />,
});
const VideoPlayer = dynamic<{ url?: string }>(() => import("@/components/product/VideoPlayer"), {
    ssr: false,
    loading: () => <MediaLoadingPlaceholder label="Loading Video..." />,
});

function MediaLoadingPlaceholder({ label }: { label: string }) {
    return (
        <div className="h-96 bg-[var(--color-navy-lighter)] rounded-xl flex items-center justify-center">
            <div className="text-center">
                <div className="w-8 h-8 border-2 border-[var(--color-gold)] border-t-transparent rounded-full animate-spin mx-auto mb-3" />
                <p className="text-sm text-[var(--color-slate)]">{label}</p>
            </div>
        </div>
    );
}

function CopyLinkButton({ productSlug, tab }: { productSlug: string, tab: string }) {
    const [copied, setCopied] = useState(false);
    const handleCopy = () => {
        const fullUrl = `${window.location.origin}/catalog/${productSlug}?tab=${tab}`;
        navigator.clipboard.writeText(fullUrl);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };
    return (
        <button onClick={handleCopy} className="absolute top-4 right-4 bg-[var(--color-navy)] bg-opacity-80 hover:bg-opacity-100 text-[var(--color-gold)] px-3 py-2 rounded-lg backdrop-blur-sm transition-all flex items-center gap-2 text-xs font-medium z-10 border border-[var(--color-border-subtle)]">
            {copied ? "✓ Copied!" : "🔗 Share Link"}
        </button>
    );
}

interface Product {
    id: string;
    name: string;
    slug: string;
    shortDescription: string | null;
    description: string | null;
    dimensions: string | null;
    weight: string | null;
    powerRequirements: string | null;
    materials: string | null;
    pricePerDay: number;
    pricePerHour: number | null;
    totalUnits: number;
    condition: string;
    installTime: number | null;
    dismantleTime: number | null;
    cleaningTime: number | null;
    manpower: string | null;
    tools: string | null;
    thumbnailUrl: string | null;
    category: { id: string; name: string; slug: string; } | null;
    media: Array<{ id: string; type: string; url: string; thumbnailUrl: string | null; alt: string | null; }>;
    documents: Array<{ id: string; name: string; url: string; size: number; }>;
    safetyCertificates: Array<{ id: string; certName: string; certNumber: string | null; issuingBody: string | null; issueDate: string; expiryDate: string; }>;
    installationGuides: Array<{ id: string; guideType: string; content: string; requiredManpower: number | null; estimatedTime: string | null; toolsRequired: string | null; }>;
    requiresLicense: boolean;
    requiresApproval: boolean;
}

export default function ProductDetailPage({ params }: { params: Promise<{ slug: string }> }) {
    const resolvedParams = React.use(params);
    const slug = resolvedParams.slug;
    const router = useRouter();
    const [product, setProduct] = useState<Product | null>(null);
    const [loading, setLoading] = useState(true);

    // Read the initial tab from URL if present
    const initialTab = typeof window !== "undefined" ? new URLSearchParams(window.location.search).get("tab") as "images" | "3d" | "video" : "images";
    const [activeTab, setActiveTab] = useState<"images" | "3d" | "video">(initialTab || "images");

    const [addingToCart, setAddingToCart] = useState(false);
    const [cartAdded, setCartAdded] = useState(false);

    // Cart form state
    const [quantity, setQuantity] = useState(1);
    const [startDate, setStartDate] = useState("");
    const [endDate, setEndDate] = useState("");

    // Availability state
    const [availability, setAvailability] = useState<{ available: boolean; unitsAvailable: number } | null>(null);
    const [checkingAvailability, setCheckingAvailability] = useState(false);

    // Guide accordion
    const [openGuide, setOpenGuide] = useState<string | null>(null);

    useEffect(() => {
        if (slug) {
            fetch(`/api/products/${slug}`)
                .then((r) => r.json())
                .then((data) => {
                    setProduct(data);
                    setLoading(false);
                })
                .catch(() => setLoading(false));
        }
    }, [slug]);

    // Simplified optimistic Add to Cart
    const addToCart = async () => {
        if (!product || !startDate || !endDate) return;
        setAddingToCart(true);
        try {
            await fetch("/api/cart", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ productId: product.id, quantity, startDate, endDate }),
            });
            setCartAdded(true);
            setTimeout(() => setCartAdded(false), 3000);

            // Dispatch custom event so the Navbar header updates its count immediately
            window.dispatchEvent(new Event("cartUpdated"));
        } catch (error) {
            console.error(error);
        }
        setAddingToCart(false);
    };

    if (loading) {
        return (
            <div className="min-h-screen pt-28 pb-16">
                <div className="max-w-7xl mx-auto px-6 animate-pulse">
                    <div className="h-8 bg-[var(--color-navy-lighter)] rounded w-1/3 mb-8" />
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                        <div className="h-96 bg-[var(--color-navy-lighter)] rounded-xl" />
                        <div className="space-y-4">
                            <div className="h-6 bg-[var(--color-navy-lighter)] rounded w-3/4" />
                            <div className="h-4 bg-[var(--color-navy-lighter)] rounded w-full" />
                            <div className="h-4 bg-[var(--color-navy-lighter)] rounded w-full" />
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    if (!product) {
        return (
            <div className="min-h-screen pt-28 flex items-center justify-center">
                <div className="text-center">
                    <h2 className="text-2xl font-bold mb-4">Product Not Found</h2>
                    <Link href="/catalog" className="btn-primary">Back to Catalog</Link>
                </div>
            </div>
        );
    }

    const images = product.media.filter((m) => m.type === "image");
    const model3d = product.media.find((m) => m.type === "model3d");
    const video = product.media.find((m) => m.type === "video");

    const conditionColor = product.condition === "excellent" ? "text-[var(--color-success)]" : product.condition === "good" ? "text-[var(--color-warning)]" : "text-[var(--color-danger)]";

    const guideTypeLabels: Record<string, string> = { install: "Installation Guide", operate: "Operation Manual", dismantle: "Dismantling Procedure" };


    return (
        <>
            <div className="min-h-screen pt-28 pb-16">
                <div className="max-w-7xl mx-auto px-6">
                    {/* Breadcrumb */}
                    <nav className="flex items-center gap-2 text-sm text-[var(--color-slate)] mb-8">
                        <Link href="/catalog" className="hover:text-[var(--color-gold)] transition-colors">Catalog</Link>
                        <span>/</span>
                        {product.category && (
                            <>
                                <Link href={`/catalog?category=${product.category.slug}`} className="hover:text-[var(--color-gold)] transition-colors">
                                    {product.category.name}
                                </Link>
                                <span>/</span>
                            </>
                        )}
                        <span className="text-[var(--color-warm-white)]">{product.name}</span>
                    </nav>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                        {/* LEFT: Media */}
                        <div>
                            {/* Tab Switcher */}
                            <div className="flex gap-1 mb-4 p-1 bg-[var(--color-surface)] rounded-xl">
                                {(["images", "3d", "video"] as const).map((tab) => (
                                    <button
                                        key={tab}
                                        onClick={() => setActiveTab(tab)}
                                        className={`flex-1 py-2.5 px-4 rounded-lg text-sm font-medium transition-all ${activeTab === tab
                                            ? "bg-[var(--color-gold)] text-[var(--color-navy)]"
                                            : "text-[var(--color-slate)] hover:text-[var(--color-warm-white)]"
                                            }`}
                                    >
                                        {tab === "images" ? "📷 Images" : tab === "3d" ? "🎲 3D Model" : "🎬 Video"}
                                    </button>
                                ))}
                            </div>

                            {/* Tab Content — Heavy media ONLY mounts when active */}
                            <div className="rounded-xl overflow-hidden">
                                {activeTab === "images" && (
                                    <div className="space-y-3">
                                        {/* Main Image */}
                                        <div className="h-80 bg-[var(--color-navy-lighter)] rounded-xl flex items-center justify-center relative overflow-hidden">
                                            {images.length > 0 ? (
                                                <>
                                                    <div className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: `url(${images[0].url})` }} />
                                                    <CopyLinkButton productSlug={product.slug} tab="images" />
                                                </>
                                            ) : (
                                                <div className="text-center text-[var(--color-slate)]">
                                                    <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1" className="mx-auto mb-2 opacity-30">
                                                        <rect x="3" y="3" width="18" height="18" rx="2" />
                                                        <circle cx="8.5" cy="8.5" r="1.5" />
                                                        <polyline points="21 15 16 10 5 21" />
                                                    </svg>
                                                    <p className="text-sm">Product images coming soon</p>
                                                </div>
                                            )}
                                        </div>
                                        {/* Thumbnail Row */}
                                        {images.length > 1 && (
                                            <div className="grid grid-cols-4 gap-2">
                                                {images.slice(0, 4).map((img) => (
                                                    <div key={img.id} className="h-20 rounded-lg bg-[var(--color-navy-lighter)] overflow-hidden cursor-pointer hover:ring-2 hover:ring-[var(--color-gold)] transition-all">
                                                        <div className="w-full h-full bg-cover bg-center" style={{ backgroundImage: `url(${img.url})` }} />
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                )}

                                {activeTab === "3d" && model3d?.url && (
                                    <div className="relative">
                                        <ModelViewer url={model3d.url} />
                                        <CopyLinkButton productSlug={product.slug} tab="3d" />
                                    </div>
                                )}
                                {activeTab === "video" && video?.url && (
                                    <div className="relative">
                                        <VideoPlayer url={video.url} />
                                        <CopyLinkButton productSlug={product.slug} tab="video" />
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* RIGHT: Specs & Actions */}
                        <div>
                            <div className="mb-2">
                                {product.category && (
                                    <span className="text-xs tracking-widest text-[var(--color-gold)] font-medium uppercase">{product.category.name}</span>
                                )}
                            </div>
                            <h1 className="font-[family-name:var(--font-heading)] text-2xl md:text-3xl font-bold text-[var(--color-warm-white)] mb-4">
                                {product.name}
                            </h1>

                            {(product.requiresLicense || product.requiresApproval) && (
                                <div className="flex flex-wrap gap-2 mb-4">
                                    {product.requiresLicense && (
                                        <div className="px-3 py-1.5 rounded-lg bg-[var(--color-navy-lighter)] border border-yellow-500/30 text-yellow-500/90 text-xs font-medium flex items-center gap-2">
                                            <span>⚠️</span> Requires Operator License
                                        </div>
                                    )}
                                    {product.requiresApproval && (
                                        <div className="px-3 py-1.5 rounded-lg bg-[var(--color-navy-lighter)] border border-red-500/30 text-red-500/90 text-xs font-medium flex items-center gap-2">
                                            <span>🏛️</span> Requires Municipal Approval
                                        </div>
                                    )}
                                </div>
                            )}

                            <p className="text-[var(--color-slate)] leading-relaxed mb-6">
                                {product.description}
                            </p>

                            {/* Price */}
                            <div className="flex items-baseline gap-4 mb-6">
                                <div>
                                    <span className="text-3xl font-bold gradient-text-gold">{product.pricePerDay} QAR</span>
                                    <span className="text-[var(--color-slate)] ml-1">/day</span>
                                </div>
                                {product.pricePerHour && (
                                    <div>
                                        <span className="text-lg text-[var(--color-slate)]">{product.pricePerHour} QAR</span>
                                        <span className="text-sm text-[var(--color-slate)] ml-0.5">/hr</span>
                                    </div>
                                )}
                            </div>

                            {/* Deep Technical Specs */}
                            <div className="glass rounded-xl p-5 mb-6">
                                <h3 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-4">TECHNICAL SPECIFICATIONS</h3>
                                <div className="grid grid-cols-2 gap-3 text-sm">
                                    {product.dimensions && (
                                        <div>
                                            <span className="text-[var(--color-slate)]">Dimensions</span>
                                            <p className="text-[var(--color-warm-white)] font-medium">{product.dimensions}</p>
                                        </div>
                                    )}
                                    {product.weight && (
                                        <div>
                                            <span className="text-[var(--color-slate)]">Weight</span>
                                            <p className="text-[var(--color-warm-white)] font-medium">{product.weight}</p>
                                        </div>
                                    )}
                                    {product.powerRequirements && (
                                        <div>
                                            <span className="text-[var(--color-slate)]">Power</span>
                                            <p className="text-[var(--color-warm-white)] font-medium">{product.powerRequirements}</p>
                                        </div>
                                    )}
                                    {product.materials && (
                                        <div>
                                            <span className="text-[var(--color-slate)]">Materials</span>
                                            <p className="text-[var(--color-warm-white)] font-medium">{product.materials}</p>
                                        </div>
                                    )}
                                    <div>
                                        <span className="text-[var(--color-slate)]">Condition</span>
                                        <p className={`font-medium capitalize ${conditionColor}`}>{product.condition.replace("_", " ")}</p>
                                    </div>
                                    <div>
                                        <span className="text-[var(--color-slate)]">In Fleet</span>
                                        <p className="text-[var(--color-warm-white)] font-medium">{product.totalUnits} units</p>
                                    </div>
                                </div>
                            </div>

                            {/* Logistics */}
                            {(product.installTime || product.dismantleTime || product.manpower) && (
                                <div className="glass rounded-xl p-5 mb-6">
                                    <h3 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-4">LOGISTICS</h3>
                                    <div className="grid grid-cols-2 gap-3 text-sm">
                                        {product.installTime !== null && product.installTime > 0 && (
                                            <div>
                                                <span className="text-[var(--color-slate)]">Install Time</span>
                                                <p className="text-[var(--color-warm-white)] font-medium">{product.installTime}h buffer</p>
                                            </div>
                                        )}
                                        {product.dismantleTime !== null && product.dismantleTime > 0 && (
                                            <div>
                                                <span className="text-[var(--color-slate)]">Dismantle Time</span>
                                                <p className="text-[var(--color-warm-white)] font-medium">{product.dismantleTime}h buffer</p>
                                            </div>
                                        )}
                                        {product.manpower && (
                                            <div className="col-span-2">
                                                <span className="text-[var(--color-slate)]">Manpower</span>
                                                <p className="text-[var(--color-warm-white)] font-medium">{product.manpower}</p>
                                            </div>
                                        )}
                                        {product.tools && (
                                            <div className="col-span-2">
                                                <span className="text-[var(--color-slate)]">Tools Required</span>
                                                <p className="text-[var(--color-warm-white)] font-medium">{product.tools}</p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}

                            {/* Safety Certificates */}
                            {product.safetyCertificates.length > 0 && (
                                <div className="glass rounded-xl p-5 mb-6">
                                    <h3 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-4">SAFETY & COMPLIANCE</h3>
                                    <div className="space-y-3">
                                        {product.safetyCertificates.map((cert) => {
                                            const isExpired = new Date(cert.expiryDate) < new Date();
                                            const isExpiringSoon = !isExpired && new Date(cert.expiryDate) < new Date(Date.now() + 90 * 24 * 60 * 60 * 1000);
                                            return (
                                                <div key={cert.id} className="flex items-center justify-between p-3 rounded-lg bg-[var(--color-navy-lighter)]">
                                                    <div>
                                                        <p className="text-sm font-medium text-[var(--color-warm-white)]">{cert.certName}</p>
                                                        <p className="text-xs text-[var(--color-slate)]">{cert.certNumber} · {cert.issuingBody}</p>
                                                    </div>
                                                    <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${isExpired ? "bg-red-500/10 text-[var(--color-danger)]" :
                                                        isExpiringSoon ? "bg-yellow-500/10 text-[var(--color-warning)]" :
                                                            "bg-green-500/10 text-[var(--color-success)]"
                                                        }`}>
                                                        {isExpired ? "Expired" : isExpiringSoon ? "Expiring Soon" : "Valid"}
                                                    </span>
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                            )}

                            {/* Documentation & Guides */}
                            {(product.installationGuides.length > 0 || (product.documents && product.documents.length > 0)) && (
                                <div className="glass rounded-xl p-5 mb-6">
                                    <h3 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-4">DOCUMENTATION</h3>

                                    {/* Uploaded Documents */}
                                    {product.documents && product.documents.length > 0 && (
                                        <div className="space-y-2 mb-4">
                                            {product.documents.map(doc => (
                                                <a key={doc.id} href={doc.url} target="_blank" rel="noopener noreferrer"
                                                    className="flex items-center justify-between p-3 rounded-lg bg-[var(--color-navy-lighter)] hover:border-[var(--color-gold)] border border-transparent transition-colors group">
                                                    <div className="flex items-center gap-3">
                                                        <span className="text-lg">📄</span>
                                                        <span className="text-sm font-medium text-[var(--color-warm-white)] group-hover:text-[var(--color-gold)] transition-colors">{doc.name}</span>
                                                    </div>
                                                    <span className="text-xs text-[var(--color-gold)] opacity-0 group-hover:opacity-100 transition-opacity">Download ↓</span>
                                                </a>
                                            ))}
                                        </div>
                                    )}

                                    {/* Installation Guides Accordion */}
                                    {product.installationGuides.length > 0 && (
                                        <div className="space-y-2">
                                            {product.installationGuides.map((guide) => (
                                                <div key={guide.id} className="rounded-lg bg-[var(--color-navy-lighter)] overflow-hidden">
                                                    <button
                                                        onClick={() => setOpenGuide(openGuide === guide.id ? null : guide.id)}
                                                        className="w-full flex items-center justify-between p-4 text-left"
                                                    >
                                                        <span className="text-sm font-medium text-[var(--color-warm-white)]">
                                                            {guideTypeLabels[guide.guideType] || guide.guideType}
                                                        </span>
                                                        <svg
                                                            width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"
                                                            className={`text-[var(--color-slate)] transition-transform ${openGuide === guide.id ? "rotate-180" : ""}`}
                                                        >
                                                            <polyline points="6 9 12 15 18 9" />
                                                        </svg>
                                                    </button>
                                                    {openGuide === guide.id && (
                                                        <div className="px-4 pb-4 text-sm text-[var(--color-slate)] whitespace-pre-line leading-relaxed border-t border-[var(--color-border-subtle)] pt-3">
                                                            {guide.content}
                                                            {(guide.requiredManpower || guide.estimatedTime || guide.toolsRequired) && (
                                                                <div className="mt-3 pt-3 border-t border-[var(--color-border-subtle)] grid grid-cols-2 gap-2 text-xs">
                                                                    {guide.requiredManpower && <div><span className="text-[var(--color-gold)]">Manpower:</span> {guide.requiredManpower} persons</div>}
                                                                    {guide.estimatedTime && <div><span className="text-[var(--color-gold)]">Est. Time:</span> {guide.estimatedTime}</div>}
                                                                    {guide.toolsRequired && <div className="col-span-2"><span className="text-[var(--color-gold)]">Tools:</span> {guide.toolsRequired}</div>}
                                                                </div>
                                                            )}
                                                        </div>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            )}

                            {/* Advanced Availability Timeline */}
                            <AvailabilityTimeline productId={product.id} />

                            {/* Add to Cart / Availability Check */}
                            <div className="glass rounded-xl p-5">
                                <h3 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)] mb-4">ADD TO CART</h3>
                                <div className="grid grid-cols-2 gap-3 mb-4">
                                    <div>
                                        <label className="text-xs text-[var(--color-slate)] mb-1 block">Start Date</label>
                                        <input type="date" value={startDate}
                                            min={new Date().toLocaleDateString('en-CA')}
                                            onChange={(e) => {
                                                setStartDate(e.target.value);
                                                if (endDate && e.target.value > endDate) {
                                                    setEndDate(e.target.value);
                                                }
                                            }}
                                            className="w-full px-3 py-2.5 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] focus:border-[var(--color-gold)] focus:outline-none text-sm" />
                                    </div>
                                    <div>
                                        <label className="text-xs text-[var(--color-slate)] mb-1 block">End Date</label>
                                        <input type="date" value={endDate}
                                            min={startDate || new Date().toLocaleDateString('en-CA')}
                                            onChange={(e) => setEndDate(e.target.value)}
                                            className="w-full px-3 py-2.5 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] focus:border-[var(--color-gold)] focus:outline-none text-sm" />
                                    </div>
                                </div>
                                <div className="mb-4">
                                    <label className="text-xs text-[var(--color-slate)] mb-1 block">Quantity</label>
                                    <div className="flex items-center gap-3">
                                        <button onClick={() => setQuantity(Math.max(1, quantity - 1))} className="w-10 h-10 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] flex items-center justify-center text-[var(--color-warm-white)] hover:border-[var(--color-gold)] transition-colors">
                                            −
                                        </button>
                                        <span className="text-lg font-semibold text-[var(--color-warm-white)] w-12 text-center">{quantity}</span>
                                        <button onClick={() => setQuantity(quantity + 1)} className="w-10 h-10 rounded-lg bg-[var(--color-navy-lighter)] border border-[var(--color-border-subtle)] flex items-center justify-center text-[var(--color-warm-white)] hover:border-[var(--color-gold)] transition-colors">
                                            +
                                        </button>
                                    </div>
                                </div>

                                {/* Availability Context (Simplified to rely on timeline) */}
                                <div className="flex items-center gap-2 mb-4 text-xs text-[var(--color-slate)]">
                                    <div className="dot-available" />
                                    <span>Subject to final approval during quoting</span>
                                </div>

                                <button
                                    onClick={addToCart}
                                    disabled={!startDate || !endDate || addingToCart}
                                    className={`w-full transition-all ${cartAdded
                                        ? "bg-green-500 text-white py-3.5 rounded-xl font-bold font-[family-name:var(--font-heading)] tracking-wider"
                                        : "btn-primary disabled:opacity-40 disabled:cursor-not-allowed"
                                        }`}
                                >
                                    {cartAdded ? "✓ ADDED TO CART" : addingToCart ? "Adding..." : "Add to Cart"}
                                </button>

                                {cartAdded && (
                                    <div className="mt-4 text-center">
                                        <Link href="/cart" className="text-sm text-[var(--color-gold)] hover:underline font-medium">
                                            View Cart →
                                        </Link>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <Footer />
        </>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { ProductCard } from "@/components/ProductCard";
import { Footer } from "@/components/Footer";

interface Product {
    id: string;
    name: string;
    slug: string;
    shortDescription: string | null;
    pricePerDay: number;
    pricePerHour: number | null;
    totalUnits: number;
    condition: string;
    thumbnailUrl: string | null;
    dimensions: string | null;
    category: { name: string; slug: string } | null;
}

interface Category {
    id: string;
    name: string;
    slug: string;
}

export default function CatalogPage() {
    const searchParams = useSearchParams();
    const initialCategory = searchParams.get("category") || "";

    const [products, setProducts] = useState<Product[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [selectedCategory, setSelectedCategory] = useState(initialCategory);
    const [searchQuery, setSearchQuery] = useState("");
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetch("/api/categories")
            .then((r) => r.json())
            .then(setCategories)
            .catch(console.error);
    }, []);

    useEffect(() => {
        setLoading(true);
        const url = selectedCategory
            ? `/api/products?category=${selectedCategory}`
            : "/api/products";
        fetch(url)
            .then((r) => r.json())
            .then((data) => {
                setProducts(data);
                setLoading(false);
            })
            .catch(() => setLoading(false));
    }, [selectedCategory]);

    const filteredProducts = products.filter((p) =>
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.shortDescription?.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <>
            <div className="min-h-screen pt-28 pb-16">
                <div className="max-w-7xl mx-auto px-6">
                    {/* Header */}
                    <div className="mb-10">
                        <h1 className="font-[family-name:var(--font-heading)] text-3xl md:text-5xl font-bold text-[var(--color-warm-white)] mb-3">
                            Equipment Catalog
                        </h1>
                        <p className="text-[var(--color-slate)] text-lg">
                            Lightweight loading — only thumbnails and specs. Click any item for full details, 3D models, and videos.
                        </p>
                    </div>

                    {/* Filters */}
                    <div className="flex flex-col sm:flex-row gap-4 mb-10">
                        {/* Search */}
                        <div className="relative flex-1">
                            <svg className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--color-slate)]" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <circle cx="11" cy="11" r="8" />
                                <line x1="21" y1="21" x2="16.65" y2="16.65" />
                            </svg>
                            <input
                                type="text"
                                placeholder="Search equipment..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full pl-12 pr-4 py-3 rounded-xl bg-[var(--color-surface)] border border-[var(--color-border-subtle)] text-[var(--color-warm-white)] placeholder:text-[var(--color-slate)] focus:border-[var(--color-gold)] focus:outline-none transition-colors"
                            />
                        </div>

                        {/* Category filter */}
                        <div className="flex gap-2 flex-wrap">
                            <button
                                onClick={() => setSelectedCategory("")}
                                className={`px-4 py-2.5 rounded-lg text-sm font-medium transition-all ${!selectedCategory
                                        ? "bg-[var(--color-gold)] text-[var(--color-navy)]"
                                        : "glass text-[var(--color-slate)] hover:text-[var(--color-gold)]"
                                    }`}
                            >
                                All
                            </button>
                            {categories.map((cat) => (
                                <button
                                    key={cat.id}
                                    onClick={() => setSelectedCategory(cat.slug)}
                                    className={`px-4 py-2.5 rounded-lg text-sm font-medium transition-all ${selectedCategory === cat.slug
                                            ? "bg-[var(--color-gold)] text-[var(--color-navy)]"
                                            : "glass text-[var(--color-slate)] hover:text-[var(--color-gold)]"
                                        }`}
                                >
                                    {cat.name}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Results count */}
                    <div className="flex items-center justify-between mb-6">
                        <p className="text-sm text-[var(--color-slate)]">
                            {filteredProducts.length} item{filteredProducts.length !== 1 ? "s" : ""} found
                        </p>
                    </div>

                    {/* Grid */}
                    {loading ? (
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                            {Array.from({ length: 8 }).map((_, i) => (
                                <div key={i} className="card animate-pulse">
                                    <div className="h-52 bg-[var(--color-navy-lighter)] rounded-t-xl" />
                                    <div className="p-5 space-y-3">
                                        <div className="h-4 bg-[var(--color-navy-lighter)] rounded w-3/4" />
                                        <div className="h-3 bg-[var(--color-navy-lighter)] rounded w-full" />
                                        <div className="h-3 bg-[var(--color-navy-lighter)] rounded w-1/2" />
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : filteredProducts.length === 0 ? (
                        <div className="text-center py-20">
                            <div className="text-5xl mb-4">🔍</div>
                            <h3 className="font-[family-name:var(--font-heading)] text-xl font-semibold text-[var(--color-warm-white)] mb-2">
                                No equipment found
                            </h3>
                            <p className="text-[var(--color-slate)]">Try adjusting your search or category filter.</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                            {filteredProducts.map((product) => (
                                <ProductCard key={product.id} {...product} />
                            ))}
                        </div>
                    )}
                </div>
            </div>
            <Footer />
        </>
    );
}

import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { bookings, products } from "@/lib/db/schema";
import { eq, desc } from "drizzle-orm";
import { redirect } from "next/navigation";
import Link from "next/link";
import { Box, LogOut, Package, Calendar, Clock, ChevronRight } from "lucide-react";

export default async function DashboardPage() {
    const user = await getCurrentUser();

    if (!user) {
        redirect("/login");
    }

    // Fetch all bookings for this user
    const userBookings = await db
        .select({
            booking: bookings,
            product: products,
        })
        .from(bookings)
        .innerJoin(products, eq(bookings.productId, products.id))
        .where(eq(bookings.userId, user.id))
        .orderBy(desc(bookings.createdAt));

    const getStatusColor = (status: string) => {
        switch (status) {
            case "pending_quote": return "bg-blue-500/10 text-blue-400 border-blue-500/20";
            case "quote_sent": return "bg-yellow-500/10 text-yellow-500 border-yellow-500/20";
            case "changes_requested": return "bg-orange-500/10 text-orange-400 border-orange-500/20";
            case "quote_accepted": return "bg-green-500/10 text-green-400 border-green-500/20";
            case "approved": return "bg-emerald-500/10 text-emerald-400 border-emerald-500/20";
            case "cancelled": return "bg-red-500/10 text-red-400 border-red-500/20";
            default: return "bg-navy-700 text-navy-300 border-navy-600";
        }
    };

    const getStatusLabel = (status: string) => {
        switch (status) {
            case "pending_quote": return "Awaiting Quote";
            case "quote_sent": return "Review Quote";
            case "changes_requested": return "Changes Requested";
            case "quote_accepted": return "Accepted";
            case "approved": return "Confirmed Booking";
            case "cancelled": return "Cancelled";
            default: return status.replace("_", " ");
        }
    };

    return (
        <div className="min-h-screen bg-[#0a0f1e] text-navy-50">
            {/* Header */}
            <header className="bg-navy-900 border-b border-navy-800 sticky top-0 z-50">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <div className="flex justify-between h-16 items-center">
                        <Link href="/" className="flex items-center gap-2 group">
                            <Box className="h-8 w-8 text-gold group-hover:scale-110 transition-transform duration-300" />
                            <span className="text-xl font-bold tracking-tight text-white uppercase font-outfit">
                                Envoy <span className="font-light text-navy-300">Rentals</span>
                            </span>
                        </Link>

                        <div className="flex items-center gap-6">
                            <span className="text-sm text-navy-300 hidden sm:block">
                                Signed in as <strong className="text-white">{user.email}</strong>
                            </span>
                            <Link href="/dashboard/profile" className="text-sm text-navy-400 hover:text-white transition-colors">
                                Profile Settings
                            </Link>
                            <form action={async () => {
                                "use server";
                                const { cookies } = await import("next/headers");
                                (await cookies()).delete("envoy_session");
                                redirect("/login");
                            }}>
                                <button type="submit" className="text-sm text-navy-400 hover:text-white flex items-center gap-2 transition-colors">
                                    <LogOut className="h-4 w-4" />
                                    Sign Out
                                </button>
                            </form>
                        </div>
                    </div>
                </div>
            </header>

            {/* Main Content */}
            <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
                <div className="md:flex md:items-center md:justify-between mb-10">
                    <div className="min-w-0 flex-1">
                        <h2 className="text-3xl font-bold leading-7 text-white sm:truncate sm:text-4xl sm:tracking-tight font-outfit">
                            Welcome back, {user.name}
                        </h2>
                        <p className="mt-2 text-lg text-navy-300">
                            Manage your equipment quotes and active bookings.
                        </p>
                    </div>
                    <div className="mt-4 flex md:ml-4 md:mt-0">
                        <Link
                            href="/catalog"
                            className="inline-flex items-center rounded-md bg-gold px-4 py-2 hover:bg-gold-400 text-sm font-bold text-navy-900 shadow-sm focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gold transition-colors"
                        >
                            Start New Quote
                        </Link>
                    </div>
                </div>

                {/* Quotes Grid */}
                <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
                    {Object.values(
                        userBookings.reduce((acc, { booking, product }) => {
                            const key = booking.projectId || booking.id;
                            if (!acc[key]) {
                                acc[key] = {
                                    id: key,
                                    projectName: booking.projectName || "Quote Request",
                                    status: booking.status,
                                    itemCount: 0,
                                    startDate: booking.startDate,
                                    endDate: booking.endDate,
                                    latestProduct: product.name,
                                };
                            }
                            acc[key].itemCount += booking.units;
                            return acc;
                        }, {} as Record<string, any>)
                    ).map((projectGroup: any) => (
                        <Link href={`/dashboard`} key={projectGroup.id} className="block group">
                            <div className="bg-navy-900 border border-navy-800 rounded-2xl p-6 shadow-sm hover:border-gold/50 hover:shadow-[0_0_30px_rgba(201,168,76,0.1)] transition-all h-full flex flex-col relative overflow-hidden">
                                {/* Status Badge */}
                                <div className="mb-6 flex justify-between items-start">
                                    <span className={`inline-flex items-center rounded-md px-2.5 py-1 text-xs font-semibold border ${getStatusColor(projectGroup.status)}`}>
                                        {getStatusLabel(projectGroup.status)}
                                    </span>
                                    {projectGroup.status === "quote_sent" && (
                                        <span className="flex h-3 w-3 relative">
                                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-gold opacity-75"></span>
                                            <span className="relative inline-flex rounded-full h-3 w-3 bg-gold"></span>
                                        </span>
                                    )}
                                </div>

                                {/* Content */}
                                <div className="flex-1">
                                    <h3 className="text-lg font-bold text-white mb-2 line-clamp-2">
                                        {projectGroup.projectName}
                                    </h3>

                                    <div className="space-y-3 mt-4">
                                        <div className="flex items-center text-sm text-navy-300">
                                            <Package className="mr-3 h-4 w-4 text-navy-400" />
                                            {projectGroup.itemCount} {projectGroup.itemCount === 1 ? 'Item' : 'Items'} requested
                                        </div>

                                        <div className="flex items-center text-sm text-navy-300">
                                            <Calendar className="mr-3 h-4 w-4 text-navy-400" />
                                            {new Date(projectGroup.startDate).toLocaleDateString()} - {new Date(projectGroup.endDate).toLocaleDateString()}
                                        </div>
                                    </div>
                                </div>

                                {/* Footer Action */}
                                <div className="mt-6 pt-4 border-t border-navy-800 flex items-center justify-between">
                                    <span className="text-sm font-medium text-gold group-hover:text-gold-300 transition-colors">
                                        View Request Items
                                    </span>
                                    <ChevronRight className="h-5 w-5 text-navy-500 group-hover:text-gold transition-colors group-hover:translate-x-1" />
                                </div>
                            </div>
                        </Link>
                    ))}

                    {userBookings.length === 0 && (
                        <div className="col-span-full py-20 text-center bg-navy-900 border border-navy-800 border-dashed rounded-2xl">
                            <Package className="mx-auto h-12 w-12 text-navy-600 mb-4" />
                            <h3 className="text-lg font-medium text-white mb-2">No quotes found</h3>
                            <p className="text-navy-400">You haven't requested any equipment yet.</p>
                        </div>
                    )}
                </div>
            </main>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Box, User, Mail, Lock, Loader2, ArrowLeft } from "lucide-react";

export default function ProfilePage() {
    const router = useRouter();
    const [name, setName] = useState("");
    const [email, setEmail] = useState(""); // readonly
    const [phoneNumber, setPhoneNumber] = useState("");
    const [password, setPassword] = useState(""); // new password
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [message, setMessage] = useState<{ text: string; type: "success" | "error" } | null>(null);

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                const res = await fetch("/api/auth/profile");
                if (!res.ok) {
                    router.push("/login");
                    return;
                }
                const data = await res.json();
                if (data.user) {
                    setName(data.user.name || "");
                    setEmail(data.user.email || "");
                    setPhoneNumber(data.user.phoneNumber || "");
                }
            } catch (err) {
                console.error("Failed to load profile:", err);
            } finally {
                setIsLoading(false);
            }
        };

        fetchProfile();
    }, [router]);

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSaving(true);
        setMessage(null);

        try {
            const res = await fetch("/api/auth/profile", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name, phoneNumber, password: password || undefined }),
            });

            const data = await res.json();
            if (!res.ok) throw new Error(data.error || "Failed to update profile");

            setMessage({ text: "Profile updated successfully!", type: "success" });
            setPassword(""); // Clear password field after save

            // Refresh to update header name if changed
            router.refresh();
        } catch (err: any) {
            setMessage({ text: err.message, type: "error" });
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="min-h-screen bg-[#0a0f1e] text-navy-50 flex items-center justify-center">
                <Loader2 className="h-8 w-8 text-gold animate-spin" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#0a0f1e] text-navy-50">
            {/* Header */}
            <header className="bg-navy-900 border-b border-navy-800 sticky top-0 z-50">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <div className="flex justify-between h-16 items-center">
                        <Link href="/dashboard" className="flex items-center gap-2 group text-navy-300 hover:text-white transition-colors">
                            <ArrowLeft className="h-5 w-5 group-hover:-translate-x-1 transition-transform" />
                            Back to Dashboard
                        </Link>
                    </div>
                </div>
            </header>

            <main className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
                <div className="mb-10">
                    <h2 className="text-3xl font-bold leading-7 text-white font-outfit">
                        Your Profile
                    </h2>
                    <p className="mt-2 text-lg text-navy-300">
                        Update your account details and security settings.
                    </p>
                </div>

                <div className="bg-navy-900 border border-navy-800 rounded-2xl p-8 shadow-sm">
                    {message && (
                        <div className={`mb-6 p-4 rounded-xl text-sm leading-relaxed border ${message.type === "success"
                                ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-400"
                                : "bg-red-500/10 border-red-500/20 text-red-400"
                            }`}>
                            {message.text}
                        </div>
                    )}

                    <form className="space-y-6" onSubmit={handleSave}>
                        <div>
                            <label className="block text-sm font-medium text-navy-200 mb-2">Email Address (Read Only)</label>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-navy-500">
                                    <Mail className="h-5 w-5" />
                                </div>
                                <input
                                    type="email"
                                    value={email}
                                    disabled
                                    className="block w-full rounded-xl border-navy-700 bg-navy-800/50 py-3 pl-10 pr-3 text-navy-300 sm:text-sm cursor-not-allowed"
                                />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-navy-200 mb-2">Full Name</label>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-navy-400">
                                    <User className="h-5 w-5" />
                                </div>
                                <input
                                    type="text"
                                    value={name}
                                    onChange={(e) => setName(e.target.value)}
                                    required
                                    className="block w-full rounded-xl border-navy-600 bg-navy-900 py-3 pl-10 pr-3 text-white placeholder-navy-400 focus:border-gold focus:ring-gold sm:text-sm transition-colors"
                                />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-navy-200 mb-2">Phone Number</label>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-navy-400">
                                    <Box className="h-5 w-5" />
                                </div>
                                <input
                                    type="tel"
                                    value={phoneNumber}
                                    onChange={(e) => setPhoneNumber(e.target.value)}
                                    className="block w-full rounded-xl border-navy-600 bg-navy-900 py-3 pl-10 pr-3 text-white placeholder-navy-400 focus:border-gold focus:ring-gold sm:text-sm transition-colors"
                                />
                            </div>
                        </div>

                        <div className="pt-6 border-t border-navy-800">
                            <h3 className="text-lg font-medium text-white mb-4">Security</h3>
                            <label className="block text-sm font-medium text-navy-200 mb-2">New Password (Leave blank to keep current)</label>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-navy-400">
                                    <Lock className="h-5 w-5" />
                                </div>
                                <input
                                    type="password"
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                    placeholder="Enter new password"
                                    minLength={6}
                                    className="block w-full rounded-xl border-navy-600 bg-navy-900 py-3 pl-10 pr-3 text-white placeholder-navy-400 focus:border-gold focus:ring-gold sm:text-sm transition-colors"
                                />
                            </div>
                        </div>

                        <div className="pt-6 flex justify-end">
                            <button
                                type="submit"
                                disabled={isSaving}
                                className="inline-flex items-center justify-center rounded-xl bg-gold px-6 py-3 text-sm font-bold text-navy-900 hover:bg-gold-400 focus:outline-none focus:ring-2 focus:ring-gold focus:ring-offset-2 focus:ring-offset-navy-900 disabled:opacity-70 disabled:cursor-not-allowed transition-all shadow-sm"
                            >
                                {isSaving ? (
                                    <span className="flex items-center gap-2"><Loader2 className="h-4 w-4 animate-spin" /> Saving...</span>
                                ) : "Save Changes"}
                            </button>
                        </div>
                    </form>
                </div>
            </main>
        </div>
    );
}

