                            </div>

                            {(quote.adminNotes || quote.notes) && (
                                <div className="card p-6 border border-[var(--color-gold)] border-opacity-20 relative overflow-hidden">
                                    <div className="absolute top-0 right-0 w-32 h-32 bg-[var(--color-gold)] opacity-5 blur-3xl rounded-full" />
                                    <h3 className="font-semibold text-[var(--color-warm-white)] mb-4 border-b border-white/10 pb-2 relative z-10">Project Details</h3>

                                    {quote.notes && (
                                        <div className="mb-4 relative z-10">
                                            <span className="flex items-center gap-2 text-xs font-semibold text-[var(--color-slate)] uppercase tracking-wider mb-2">
                                                <span className="w-4 h-px bg-white/20" /> Your Original Request
                                            </span>
                                            <p className="text-sm text-[var(--color-warm-white)] pl-6 border-l-2 border-white/10 italic">
                                                "{quote.notes}"
                                            </p>
                                        </div>
                                    )}

                                    {quote.adminNotes && (
                                        <div className="relative z-10">
                                            <span className="flex items-center gap-2 text-xs font-semibold text-[var(--color-gold)] uppercase tracking-wider mb-2 mt-6">
                                                <span className="w-4 h-px bg-[var(--color-gold)] opacity-30" /> Message from Reyati
                                            </span>
                                            <div className="p-4 bg-[var(--color-gold)] bg-opacity-5 rounded-lg border border-[var(--color-gold)] border-opacity-20 text-sm text-[var(--color-warm-white)]">
                                                {quote.adminNotes}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>

                        {/* Pricing Column */}
                        <div className="space-y-6">
                            <div className="glass rounded-xl p-6 md:p-8">
                                <h3 className="font-semibold text-[var(--color-warm-white)] mb-6 border-b border-[var(--color-border-subtle)] pb-4 tracking-wider uppercase text-sm">Official Quote</h3>

                                <div className="space-y-4 mb-6 text-sm">
                                    <div className="flex justify-between items-center pb-2 border-b border-white/5">
                                        <span className="text-[var(--color-slate)]">Base Hardware Rental</span>
                                        <span className="text-[var(--color-warm-white)]">{baseRental.toLocaleString()} QAR</span>
                                    </div>

                                    {quote.discount > 0 && (
                                        <div className="flex justify-between items-center text-[var(--color-success)] pb-2 border-b border-white/5">
                                            <span>Partner Discount ({quote.discount}%)</span>
                                            <span>-{discountAmount.toLocaleString()} QAR</span>
                                        </div>
                                    )}

                                    {quote.logisticsCost > 0 && (
                                        <div className="flex justify-between items-center pb-2 border-b border-white/5">
                                            <span className="text-[var(--color-slate)]">Logistics & Transport</span>
                                            <span className="text-[var(--color-warm-white)]">{quote.logisticsCost.toLocaleString()} QAR</span>
                                        </div>
                                    )}

                                    {quote.laborCost > 0 && (
                                        <div className="flex justify-between items-center pb-2 border-b border-white/5">
                                            <span className="text-[var(--color-slate)]">Install & Dismantle Labor</span>
                                            <span className="text-[var(--color-warm-white)]">{quote.laborCost.toLocaleString()} QAR</span>
                                        </div>
                                    )}

                                    {quote.customFee > 0 && (
                                        <div className="flex justify-between items-center pb-2 border-b border-white/5">
                                            <span className="text-[var(--color-slate)]">Custom Project Fee</span>
                                            <span className="text-[var(--color-warm-white)]">{quote.customFee.toLocaleString()} QAR</span>
                                        </div>
                                    )}

                                    <div className="flex justify-between items-center pb-2 text-[var(--color-slate)]">
                                        <span>Tax ({quote.taxRate}%)</span>
                                        <span>{tax.toLocaleString()} QAR</span>
                                    </div>
                                </div>

                                <div className="flex justify-between items-end pt-4 mb-8">
                                    <span className="text-[var(--color-warm-white)] font-bold text-lg">Total Due</span>
                                    <span className="text-3xl font-bold gradient-text-gold">{grandTotal.toLocaleString()} QAR</span>
                                </div>

                                {/* Call to Actions */}
                                {canRespond ? (
                                    <div className="space-y-4 pt-6 border-t border-[var(--color-gold)] border-opacity-20">
                                        {!showRevisionForm ? (
                                            <>
                                                <button
                                                    onClick={() => handleAction("accept")}
                                                    disabled={submitting}
                                                    className="w-full btn-primary bg-[var(--color-gold)] text-[var(--color-navy)] py-3.5 text-base shadow-[0_0_20px_rgba(207,181,59,0.3)] hover:shadow-[0_0_30px_rgba(207,181,59,0.5)] border-none"
                                                >
                                                    {submitting ? "Processing..." : "Accept & Proceed"}
                                                </button>
                                                <button
                                                    onClick={() => setShowRevisionForm(true)}
                                                    disabled={submitting}
                                                    className="w-full py-3 rounded-lg border border-white/10 hover:border-white/30 text-sm font-medium text-[var(--color-slate)] hover:text-[var(--color-warm-white)] transition-all bg-white/5 hover:bg-white/10"
                                                >
                                                    Request Changes
                                                </button>
                                            </>
                                        ) : (
                                            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
                                                <label className="block text-sm font-medium text-[var(--color-warm-white)] mb-2">
                                                    What changes do you need?
                                                </label>
                                                <textarea
                                                    value={clientMessage}
                                                    onChange={(e) => setClientMessage(e.target.value)}
                                                    placeholder="E.g., Can we extend the rental by 1 day? Is there flexibility on the labor cost?"
                                                    rows={4}
                                                    className="w-full bg-[var(--color-navy-dark)] border border-white/10 rounded-lg px-3 py-2 text-sm text-[var(--color-warm-white)] focus:border-[var(--color-gold)] outline-none resize-none mb-3"
                                                />
                                                <div className="flex gap-3">
                                                    <button
                                                        onClick={() => setShowRevisionForm(false)}
                                                        className="flex-1 py-2.5 rounded-lg border border-white/10 text-sm font-medium text-[var(--color-slate)] hover:text-[var(--color-warm-white)] transition-all bg-white/5"
                                                    >
                                                        Cancel
                                                    </button>
                                                    <button
                                                        onClick={() => handleAction("revise")}
                                                        disabled={submitting}
                                                        className="flex-1 btn-primary py-2.5"
                                                    >
                                                        {submitting ? "Sending..." : "Submit Revision"}
                                                    </button>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                ) : (
                                    <div className="pt-6 border-t border-[var(--color-gold)] border-opacity-20 text-center">
                                        <p className="text-sm font-medium text-white mb-2">Quote is Locked</p>
                                        <p className="text-xs text-[var(--color-slate)]">
                                            This quote has already been responded to. Please contact your account manager if you need further adjustments.
                                        </p>
                                    </div>
                                )}

                            </div>
                        </div>

                    </div>

                </div>
            </div>
            <Footer />
        </>
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Box, Lock, Mail, ArrowRight, Loader2, User } from "lucide-react";

export default function SignupPage() {
    const router = useRouter();
    const [nameState, setNameState] = useState("");
    const [emailState, setEmailState] = useState("");
    const [phoneState, setPhoneState] = useState("");
    const [passwordState, setPasswordState] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError(null);

        try {
            const res = await fetch("/api/auth/signup", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    name: nameState,
                    email: emailState,
                    phoneNumber: phoneState,
                    password: passwordState
                }),
            });

            const data = await res.json();

            if (!res.ok) {
                throw new Error(data.error || "Failed to sign up");
            }

            // Immediately log them in
            await fetch("/api/auth/login", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ email: emailState, password: passwordState }),
            });

            router.push("/dashboard");
            router.refresh();
        } catch (err: any) {
            setError(err.message);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-navy text-navy-50 flex flex-col justify-center py-12 sm:px-6 lg:px-8 relative overflow-hidden">
            <div className="absolute top-0 right-0 -mr-32 -mt-32 w-96 h-96 rounded-full bg-gold/10 blur-3xl opacity-50 pointer-events-none" />
            <div className="absolute bottom-0 left-0 -ml-32 -mb-32 w-96 h-96 rounded-full bg-navy-400/20 blur-3xl opacity-50 pointer-events-none" />

            <div className="sm:mx-auto sm:w-full sm:max-w-md relative z-10">
                <Link href="/" className="flex items-center justify-center gap-2 mb-8 group">
                    <Box className="h-10 w-10 text-gold group-hover:scale-110 transition-transform duration-300" />
                    <span className="text-2xl font-bold tracking-tight text-white uppercase font-outfit">
                        Envoy <span className="font-light text-navy-300">Rentals</span>
                    </span>
                </Link>
                <h2 className="mt-6 text-center text-3xl font-bold tracking-tight text-white font-outfit">
                    Create an account
                </h2>
                <p className="mt-2 text-center text-sm text-navy-300">
                    Already have an account?{" "}
                    <Link href="/login" className="font-medium text-gold hover:text-gold-300 transition-colors">
                        Log in here
                    </Link>
                </p>
            </div>

            <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md relative z-10">
                <div className="bg-navy-800/50 backdrop-blur-xl py-8 px-4 shadow-[0_0_40px_rgba(0,0,0,0.3)] sm:rounded-2xl sm:px-10 border border-navy-700">
                    <form className="space-y-6" onSubmit={handleSubmit}>
                        {error && (
                            <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-xl text-sm leading-relaxed">
                                {error}
                            </div>
                        )}

                        <div>
                            <label className="block text-sm font-medium text-navy-200" htmlFor="name">Full Name</label>
                            <div className="mt-2 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-navy-400">
                                    <User className="h-5 w-5" />
                                </div>
                                <input id="name" type="text" value={nameState} onChange={(e) => setNameState(e.target.value)} className="block w-full rounded-xl border-navy-600 bg-navy-900/50 py-3 pl-10 pr-3 text-white placeholder-navy-400 focus:border-gold focus:ring-gold sm:text-sm shadow-inner transition-colors" placeholder="John Doe" required />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-navy-200" htmlFor="email">Email Address</label>
                            <div className="mt-2 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-navy-400">
                                    <Mail className="h-5 w-5" />
                                </div>
                                <input id="email" type="email" value={emailState} onChange={(e) => setEmailState(e.target.value)} className="block w-full rounded-xl border-navy-600 bg-navy-900/50 py-3 pl-10 pr-3 text-white placeholder-navy-400 focus:border-gold focus:ring-gold sm:text-sm shadow-inner transition-colors" placeholder="hello@company.com" required />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-navy-200" htmlFor="phone">Phone Number</label>
                            <div className="mt-2 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-navy-400">
                                    <Box className="h-5 w-5" />
                                </div>
                                <input id="phone" type="tel" value={phoneState} onChange={(e) => setPhoneState(e.target.value)} className="block w-full rounded-xl border-navy-600 bg-navy-900/50 py-3 pl-10 pr-3 text-white placeholder-navy-400 focus:border-gold focus:ring-gold sm:text-sm shadow-inner transition-colors" placeholder="+974 5555 5555" />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-navy-200" htmlFor="password">Password</label>
                            <div className="mt-2 relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-navy-400">
                                    <Lock className="h-5 w-5" />
                                </div>
                                <input id="password" type="password" value={passwordState} onChange={(e) => setPasswordState(e.target.value)} className="block w-full rounded-xl border-navy-600 bg-navy-900/50 py-3 pl-10 pr-3 text-white placeholder-navy-400 focus:border-gold focus:ring-gold sm:text-sm shadow-inner transition-colors" placeholder="Choose a secure password" required minLength={6} />
                            </div>
                        </div>

                        <div>
                            <button type="submit" disabled={isLoading} className="group relative flex w-full justify-center rounded-xl bg-gold px-4 py-3 text-sm font-bold text-navy-900 hover:bg-gold-400 focus:outline-none focus:ring-2 focus:ring-gold focus:ring-offset-2 focus:ring-offset-navy-900 disabled:opacity-70 disabled:cursor-not-allowed transition-all shadow-[0_0_20px_rgba(201,168,76,0.2)] hover:shadow-[0_0_25px_rgba(201,168,76,0.4)]">
                                {isLoading ? (
                                    <span className="flex items-center gap-2"><Loader2 className="h-5 w-5 animate-spin" /> Creating Account...</span>
                                ) : (
                                    <span className="flex items-center gap-2">Create Account <ArrowRight className="h-4 w-4 group-hover:translate-x-1 transition-transform" /></span>
                                )}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
}

"use client";

import Link from "next/link";
import { useState, useEffect } from "react";

export function Navbar() {
    const [scrolled, setScrolled] = useState(false);
    const [mobileOpen, setMobileOpen] = useState(false);
    const [cartCount, setCartCount] = useState(0);
    const [user, setUser] = useState<any>(null);

    useEffect(() => {
        const handleScroll = () => setScrolled(window.scrollY > 50);
        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    useEffect(() => {
        fetch("/api/cart")
            .then((r) => r.json())
            .then((items) => {
                if (Array.isArray(items)) setCartCount(items.length);
            })
            .catch(() => { });

        fetch("/api/auth/me")
            .then((r) => r.json())
            .then((data) => {
                if (data.user) setUser(data.user);
            })
            .catch(() => { });
    }, []);

    return (
        <nav
            className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${scrolled
                ? "glass py-3"
                : "bg-transparent py-5"
                }`}
        >
            <div className="max-w-7xl mx-auto px-6 flex items-center justify-between">
                {/* Logo */}
                <Link href="/" className="flex items-center gap-3 group">
                    <div className="w-10 h-10 rounded-lg gradient-gold flex items-center justify-center">
                        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0a0f1e" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                            <polygon points="12 2 22 8.5 22 15.5 12 22 2 15.5 2 8.5 12 2" />
                            <line x1="12" y1="22" x2="12" y2="15.5" />
                            <polyline points="22 8.5 12 15.5 2 8.5" />
                        </svg>
                    </div>
                    <span className="text-xl font-bold font-[family-name:var(--font-heading)] tracking-wider">
                        <span className="gradient-text-gold">ENVOY</span>
                        <span className="text-[var(--color-slate)] font-light ml-1 text-sm tracking-widest">RENTALS</span>
                    </span>
                </Link>

                {/* Desktop Nav */}
                <div className="hidden md:flex items-center gap-8">
                    <Link href="/catalog" className="text-sm tracking-wide text-[var(--color-slate)] hover:text-[var(--color-gold)] transition-colors duration-300">
                        Catalog
                    </Link>
                    <Link href="/catalog?category=staging-trusses" className="text-sm tracking-wide text-[var(--color-slate)] hover:text-[var(--color-gold)] transition-colors duration-300">
                        Staging
                    </Link>
                    <Link href="/catalog?category=lighting" className="text-sm tracking-wide text-[var(--color-slate)] hover:text-[var(--color-gold)] transition-colors duration-300">
                        Lighting
                    </Link>
                    <Link href="/catalog?category=sound-audio" className="text-sm tracking-wide text-[var(--color-slate)] hover:text-[var(--color-gold)] transition-colors duration-300">
                        Sound
                    </Link>

                    {user?.role === "admin" && (
                        <Link href="/admin" className="text-sm tracking-wide text-[var(--color-slate)] hover:text-[var(--color-gold)] transition-colors duration-300">
                            Admin
                        </Link>
                    )}

                    {user ? (
                        <Link href="/dashboard" className="text-sm tracking-wide text-[var(--color-gold)] font-medium hover:text-[var(--color-gold-lighter)] transition-colors duration-300">
                            Dashboard
                        </Link>
                    ) : (
                        <Link href="/login" className="text-sm tracking-wide text-[var(--color-slate)] hover:text-[var(--color-gold)] transition-colors duration-300">
                            Sign In
                        </Link>
                    )}
                </div>

                {/* Actions */}
                <div className="flex items-center gap-4">
                    <Link
                        href="/cart"
                        className="relative p-2 rounded-lg hover:bg-[var(--color-navy-lighter)] transition-colors"
                    >
                        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                            <circle cx="9" cy="21" r="1" />
                            <circle cx="20" cy="21" r="1" />
                            <path d="m1 1 4 0 2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6" />
                        </svg>
                        {cartCount > 0 && (
                            <span className="absolute -top-1 -right-1 w-5 h-5 bg-[var(--color-gold)] text-[var(--color-navy)] text-xs font-bold rounded-full flex items-center justify-center">
                                {cartCount}
                            </span>
                        )}
                    </Link>

                    <Link href="/catalog" className="hidden md:inline-flex btn-primary text-sm !py-2 !px-5">
                        Browse Fleet
                    </Link>

                    {/* Mobile toggle */}
                    <button
                        className="md:hidden p-2"
                        onClick={() => setMobileOpen(!mobileOpen)}
                    >
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                            {mobileOpen ? (
                                <>
                                    <line x1="18" y1="6" x2="6" y2="18" />
                                    <line x1="6" y1="6" x2="18" y2="18" />
                                </>
                            ) : (
                                <>
                                    <line x1="3" y1="6" x2="21" y2="6" />
                                    <line x1="3" y1="12" x2="21" y2="12" />
                                    <line x1="3" y1="18" x2="21" y2="18" />
