            </div>

            {/* Mobile Menu */}
            {mobileOpen && (
                <div className="md:hidden glass mt-2 mx-4 rounded-xl p-6 animate-fade-up">
                    <div className="flex flex-col gap-4">
                        <Link href="/catalog" onClick={() => setMobileOpen(false)} className="text-[var(--color-warm-white)] hover:text-[var(--color-gold)] transition-colors">
