"use client";

import { useState, useEffect } from "react";
import { format, parseISO } from "date-fns";

interface TimelineDay {
    date: string;
    available: number;
    total: number;
}

export default function AvailabilityTimeline({ productId }: { productId: string }) {
    const [timeline, setTimeline] = useState<TimelineDay[]>([]);
    const [loading, setLoading] = useState(true);
    const [hoveredDay, setHoveredDay] = useState<TimelineDay | null>(null);

    useEffect(() => {
        fetch(`/api/availability/timeline/${productId}`)
            .then(res => res.json())
            .then(data => {
                if (Array.isArray(data)) setTimeline(data);
                setLoading(false);
            })
            .catch(() => setLoading(false));
    }, [productId]);

    if (loading) {
        return <div className="animate-pulse h-24 bg-[var(--color-navy-lighter)] rounded-xl mb-6"></div>;
    }

    if (timeline.length === 0) return null;

    // Split into "Available Now" (today) and the rest of the timeline
    const today = timeline[0];

    return (
        <div className="glass rounded-xl p-5 mb-6">
            <div className="flex items-center justify-between mb-4">
                <h3 className="font-[family-name:var(--font-heading)] font-semibold text-sm tracking-wider text-[var(--color-gold)]">
                    AVAILABILITY FORECAST
                </h3>
            </div>

            {/* Current Status */}
            <div className="flex items-center gap-3 mb-5">
                <div className="w-12 h-12 rounded-lg bg-[var(--color-navy-lighter)] flex items-center justify-center border border-[var(--color-border-subtle)] shrink-0">
                    <span className="text-xl font-bold text-[var(--color-warm-white)]">{today.available}</span>
                </div>
                <div>
                    <h4 className="text-[var(--color-warm-white)] font-medium">Available Right Now</h4>
                    <p className="text-xs text-[var(--color-slate)]">Out of {today.total} total units in fleet</p>
                </div>
            </div>

            {/* 30-Day Timeline Visualizer */}
            <div className="relative group">
                <div className="flex items-end h-16 gap-[2px] w-full">
                    {timeline.map((day, i) => {
                        const heightPercent = Math.max(10, (day.available / day.total) * 100);
                        const isOut = day.available === 0;
                        const isLow = day.available > 0 && (day.available / day.total) <= 0.2;

                        return (
                            <div
                                key={day.date}
                                onMouseEnter={() => setHoveredDay(day)}
                                onMouseLeave={() => setHoveredDay(null)}
                                className="flex-1 rounded-t-sm transition-colors cursor-crosshair opacity-80 hover:opacity-100"
                                style={{
                                    height: `${heightPercent}%`,
                                    backgroundColor: isOut ? 'var(--color-danger)' : isLow ? 'var(--color-warning)' : 'var(--color-success)'
                                }}
                            />
                        );
                    })}
                </div>

                {/* X-Axis Labels */}
                <div className="flex justify-between text-[10px] text-[var(--color-slate)] mt-1 font-medium">
                    <span>Today</span>
                    <span>15 Days</span>
                    <span>30 Days</span>
                </div>

                {/* Hover Tooltip */}
                {hoveredDay && (
                    <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-[var(--color-navy-light)] border border-[var(--color-border-subtle)] shadow-xl rounded-lg p-2 flex items-center gap-3 z-10 pointer-events-none whitespace-nowrap">
                        <div className="text-right">
                            <span className="block text-xs font-bold text-[var(--color-warm-white)]">
                                {format(parseISO(hoveredDay.date), "MMM do, yyyy")}
                            </span>
                        </div>
                        <div className="w-px h-6 bg-[var(--color-border-subtle)]" />
                        <div>
                            <span className="text-sm font-bold text-[var(--color-gold)]">{hoveredDay.available}</span>
                            <span className="text-xs text-[var(--color-slate)] ml-1">units</span>
                        </div>
                    </div>
                )}
            </div>
            <p className="text-[10px] text-[var(--color-slate)] mt-4 text-center">
                Hover over the timeline to see exact daily unit counts factoring in logistics buffers.
            </p>
        </div>
    );
}

import { jwtVerify, SignJWT } from "jose";
import { cookies } from "next/headers";
import { db } from "./db";
import { users } from "./db/schema";
import { eq } from "drizzle-orm";

const SECRET_KEY = new TextEncoder().encode(
    process.env.JWT_SECRET || "default_super_secret_key_for_development"
);

export async function signToken(payload: { id: string; email: string; role: string }) {
    return new SignJWT(payload)
        .setProtectedHeader({ alg: "HS256" })
        .setIssuedAt()
        .setExpirationTime("7d")
        .sign(SECRET_KEY);
}

export async function verifyToken(token: string) {
    try {
        const { payload } = await jwtVerify(token, SECRET_KEY);
        return payload as { id: string; email: string; role: string };
    } catch (error) {
        return null;
    }
}

export async function getSession() {
    const cookieStore = await cookies();
    const token = cookieStore.get("envoy_session")?.value;
    if (!token) return null;

    return await verifyToken(token);
}

export async function getCurrentUser() {
    const session = await getSession();
    if (!session) return null;

    const [user] = await db
        .select()
        .from(users)
        .where(eq(users.id, session.id))
        .limit(1);

    return user || null;
}

import { db } from "./db";
import { products, bookings, inventoryOverrides } from "./db/schema";
import { eq, and, or, lte, gte, inArray } from "drizzle-orm";
import { addHours, subHours, parseISO } from "date-fns";

export interface AvailabilityRequest {
    productId: string;
    startDate: string; // YYYY-MM-DD
    endDate: string;   // YYYY-MM-DD
    quantity: number;
    startTime?: string; // HH:mm — for multi-shift
    endTime?: string;   // HH:mm — for multi-shift
}

export interface AvailabilityResult {
    available: boolean;
    unitsAvailable: number;
    totalUnits: number;
    requestedQuantity: number;
    effectiveStart: string;
    effectiveEnd: string;
    conflictingBookings: number;
}

/**
 * Core Availability Engine
 * 
 * Handles:
 * 1. Basic date overlap detection
 * 2. Buffer days (installation + dismantling time)
 * 3. Multi-shift same-day turnarounds with hour-level precision
 * 4. Manual inventory overrides (maintenance, manual holds)
 */
export async function checkAvailability(req: AvailabilityRequest): Promise<AvailabilityResult> {
    // 1. Fetch product details
    const product = await db.query.products.findFirst({
        where: eq(products.id, req.productId),
    });

    if (!product) {
        throw new Error(`Product not found: ${req.productId}`);
    }

    const installHours = product.installTime || 0;
    const dismantleHours = product.dismantleTime || 0;
    const cleaningHours = product.cleaningTime || 0;

    // 2. Calculate effective date window with buffer
    //    effectiveStart = requestedStart - installTime
    //    effectiveEnd = requestedEnd + dismantleTime
    const requestedStart = parseISO(req.startDate);
    const requestedEnd = parseISO(req.endDate);

    const effectiveStart = subHours(requestedStart, installHours);
    const effectiveEnd = addHours(requestedEnd, dismantleHours);

    const effectiveStartStr = effectiveStart.toISOString().split("T")[0];
    const effectiveEndStr = effectiveEnd.toISOString().split("T")[0];

    // 3. Query all bookings that could overlap
    //    Overlap condition: effectiveStart <= booking.effectiveEnd AND effectiveEnd >= booking.effectiveStart
    //    Only count approved, booked, and quote_accepted statuses
    //    We explicitly IGNORE pending_quote, quote_sent, changes_requested, cancelled, undelivered
    const overlappingBookings = await db.query.bookings.findMany({
        where: and(
            eq(bookings.productId, req.productId),
            inArray(bookings.status, ["quote_accepted", "approved", "booked"]),
            lte(bookings.startDate, effectiveEndStr),
            gte(bookings.endDate, effectiveStartStr),
        ),
    });

    // 4. Filter for actual overlaps considering buffer times and multi-shift logic
    let overlappingUnits = 0;

    for (const booking of overlappingBookings) {
        const bookingStart = parseISO(booking.startDate);
        const bookingEnd = parseISO(booking.endDate);
        const bookingEffectiveStart = subHours(bookingStart, booking.bufferBefore || 0);
        const bookingEffectiveEnd = addHours(bookingEnd, booking.bufferAfter || 0);

        // Check if the effective windows truly overlap
        if (effectiveStart <= bookingEffectiveEnd && effectiveEnd >= bookingEffectiveStart) {

            // Multi-shift check: if both bookings have time ranges on the same day,
            // check if times actually overlap (including cleaning buffer)
            if (req.startTime && req.endTime && booking.startTime && booking.endTime &&
                req.startDate === req.endDate && booking.startDate === booking.endDate &&
                req.startDate === booking.startDate) {

                const reqStartMinutes = timeToMinutes(req.startTime);
                const reqEndMinutes = timeToMinutes(req.endTime);
                const bookStartMinutes = timeToMinutes(booking.startTime);
                const bookEndMinutes = timeToMinutes(booking.endTime) + (cleaningHours * 60);

                // No time overlap → same-day turnaround is OK
                if (reqStartMinutes >= bookEndMinutes || reqEndMinutes <= bookStartMinutes) {
                    continue; // This booking doesn't actually conflict
                }
            }

            overlappingUnits += booking.units;
        }
    }

    // 5. Query manual inventory overrides
    const overrides = await db.query.inventoryOverrides.findMany({
        where: and(
            eq(inventoryOverrides.productId, req.productId),
            lte(inventoryOverrides.startDate, effectiveEndStr),
            gte(inventoryOverrides.endDate, effectiveStartStr),
        ),
    });

    for (const over of overrides) {
        overlappingUnits += over.unitsOffline;
    }

    const unitsAvailable = product.totalUnits - overlappingUnits;

    return {
        available: unitsAvailable >= req.quantity,
        unitsAvailable: Math.max(0, unitsAvailable),
        totalUnits: product.totalUnits,
        requestedQuantity: req.quantity,
        effectiveStart: effectiveStartStr,
        effectiveEnd: effectiveEndStr,
        conflictingBookings: overlappingBookings.length,
    };
}


/** Convert "HH:mm" to total minutes since midnight */
function timeToMinutes(time: string): number {
    const [hours, minutes] = time.split(":").map(Number);
    return hours * 60 + minutes;
}

/**
 * Calculates a day-by-day availability timeline for the next N days.
 * Returns an array of available units per date.
 * Does not check time windows — returns the MINIMUM available stock for each day.
 */
export async function getAvailabilityTimeline(productId: string, lookaheadDays: number = 30) {
    const today = new Date();
    // Normalize to start of day
    today.setHours(0, 0, 0, 0);

    const timeline: { date: string; available: number; total: number }[] = [];

    // First, check product total units
    const product = await db.query.products.findFirst({
        where: eq(products.id, productId),
    });

    if (!product) return timeline;

    // Loop through the days to check
    for (let i = 0; i < lookaheadDays; i++) {
        const currentDate = new Date(today);
        currentDate.setDate(today.getDate() + i);
        const dateStr = currentDate.toISOString().split("T")[0];

        // Call the core engine for a 1-day block
        // (This naturally handles the padding for install/dismantle buffers required even for a 1-day rental)
        const dayCheck = await checkAvailability({
            productId: productId,
            startDate: dateStr,
            endDate: dateStr,
            quantity: 1, // Quantity doesn't matter for the raw unit count
        });

        timeline.push({
            date: dateStr,
            available: dayCheck.unitsAvailable,
            total: product.totalUnits,
        });
    }

    return timeline;
}

